export const ENCYCLOPEDIA: EncyItem[] = [
  // ===== 초기 공개분 (40개) =====
  { term: '임플란트', reading: 'Implant', category: '치료·시술', def: '상실된 치아 자리에 티타늄 재질의 인공치근(픽스처)을 잇몸뼈에 심고, 뼈와 단단히 붙는 골유착 과정을 거친 뒤 그 위에 기둥(어버트먼트)과 크라운을 연결해 치아의 기능과 모양을 회복하는 치료입니다. 틀니와 달리 잇몸뼈에 직접 고정되기 때문에 씹는 힘이 자연치아의 80~90% 수준까지 회복되며, 브릿지처럼 옆의 건강한 치아를 깎지 않아도 된다는 것이 큰 장점입니다. 치료 기간은 뼈 상태에 따라 다르지만 통상 골유착에 2~6개월이 걸리고, 뼈가 부족한 경우 뼈이식이 함께 진행되면 기간이 더 길어질 수 있습니다. 임플란트 자체는 충치가 생기지 않지만 주변 잇몸에는 염증(임플란트 주위염)이 생길 수 있으므로, 시술 후에도 정기검진과 꼼꼼한 잇몸 관리가 반드시 필요합니다. 식립 전에는 CT로 신경관 위치와 뼈의 폭·밀도를 정확히 파악하는 정밀 진단이 중요합니다.', related: 'implant' },
  { term: '라미네이트', reading: 'Laminate Veneer', category: '치료·시술', def: '치아의 앞면에 얇은 세라믹 조각(베니어)을 부착해 치아의 모양, 색, 크기, 배열을 개선하는 심미 치료입니다. 손톱에 붙이는 인조 손톱처럼 치아 표면에 맞춤 제작한 세라믹을 접착하는 원리로, 변색된 치아, 벌어진 앞니, 작거나 비대칭인 치아를 비교적 짧은 기간에 개선할 수 있습니다. 전통적인 방식은 치아 표면을 0.5mm 내외로 삭제했지만, 최근에는 치아 삭제를 최소화하거나 아예 삭제하지 않는 무삭제·최소삭제 방식이 발전해 자연치아의 손상을 크게 줄일 수 있게 되었습니다. 삭제량이 적을수록 시린 증상이나 신경 손상 위험이 낮고, 유지 관리에도 유리합니다. 다만 이갈이가 심하거나 교합이 맞지 않는 경우 파절 위험이 있어, 시술 전 교합 상태와 치아 상태에 대한 정밀한 진단이 중요합니다. 관리만 잘하면 10년 이상 사용할 수 있습니다.', related: 'bloomnate' },
  { term: '신경치료', reading: 'Root Canal Treatment', category: '치료·시술', def: '충치나 외상으로 치아 내부의 신경조직(치수)이 감염되거나 손상됐을 때, 감염된 신경을 제거하고 신경이 있던 빈 공간(근관)을 소독한 뒤 특수 재료로 밀봉해 치아를 뽑지 않고 살리는 치료입니다. 흔히 신경을 죽이는 치료로 오해하지만, 정확히는 이미 병든 신경을 제거해 치아 자체를 보존하는 치료입니다. 어금니의 근관은 3~4개 이상으로 가늘고 휘어져 있어 육안으로 모두 찾기 어려운 경우가 많은데, 미세현미경을 사용하면 치료 부위를 수십 배 확대해 숨은 근관과 미세한 균열까지 확인할 수 있어 치료 성공률이 크게 올라갑니다. 신경치료를 마친 치아는 수분 공급이 끊겨 깨지기 쉬워지므로, 대부분 크라운을 씌워 보호합니다. 치료 중에는 여러 번 내원이 필요할 수 있으며, 중간에 치료를 멈추면 재감염 위험이 커지므로 끝까지 완료하는 것이 중요합니다.', related: 'endo' },
  { term: '크라운', reading: 'Crown', category: '치료·시술', def: '충치나 파절로 손상 범위가 큰 치아, 신경치료를 마친 치아를 전체적으로 감싸 보호하는 보철물입니다. 치아에 왕관을 씌우듯 덮는다고 해서 크라운이라는 이름이 붙었습니다. 남은 치아의 양이 적어 레진이나 인레이로 때우기 어려울 때, 치아가 깨지지 않도록 전체를 감싸 씹는 힘을 견디게 해주는 역할을 합니다. 재료는 강도가 높고 잇몸 변색이 없는 지르코니아, 자연치아와 가장 유사한 투명도를 내는 세라믹, 오래 검증된 골드 등이 있으며, 위치와 교합력, 심미성을 고려해 선택합니다. 제작 과정은 치아를 다듬고 본을 뜬 뒤 기공 과정을 거쳐 접착하며, 통상 1~2주가 소요됩니다. 크라운을 씌운 치아도 경계 부위에 충치(이차우식)가 생길 수 있으므로 잇몸 경계선까지 꼼꼼히 닦는 습관과 정기검진이 수명을 좌우합니다. 잘 관리하면 10년 이상 사용이 가능합니다.', related: 'prosthetics' },
  { term: '브릿지', reading: 'Bridge', category: '치료·시술', def: '치아가 빠진 자리를 기준으로 양옆의 치아를 기둥 삼아 다리를 놓듯 연결하는 보철 치료입니다. 빠진 치아 양쪽의 치아를 다듬어 크라운을 씌우고, 그 사이에 인공치아를 연결한 일체형 보철물을 접착합니다. 수술 없이 비교적 짧은 기간에 치아를 회복할 수 있고, 전신 질환 등으로 임플란트 수술이 어려운 분에게 좋은 대안이 됩니다. 다만 건강한 양옆 치아를 삭제해야 한다는 점, 기둥 치아 두 개가 세 개 몫의 씹는 힘을 부담하게 된다는 점이 단점입니다. 연결 부위 아래는 칫솔이 잘 닿지 않아 음식물이 고이기 쉬우므로, 브릿지 전용 치실(슈퍼플로스)이나 치간칫솔로 관리해야 수명을 늘릴 수 있습니다. 평균 수명은 관리 상태에 따라 7~10년 내외이며, 기둥 치아에 문제가 생기면 브릿지 전체를 다시 제작해야 할 수 있어 정기적인 점검이 특히 중요합니다.', related: 'prosthetics' },
  { term: '스케일링', reading: 'Scaling', category: '치료·시술', def: '치아 표면과 잇몸 경계에 붙은 치석과 세균막(플라크)을 초음파 기구로 제거하는 잇몸 질환 예방·치료의 기본 술식입니다. 치석은 양치질로 제거되지 않은 플라크가 침 속의 미네랄과 결합해 딱딱하게 굳은 것으로, 표면이 거칠어 세균이 더 잘 붙는 악순환을 만듭니다. 치석 속 세균은 잇몸 염증을 일으키고, 방치하면 잇몸뼈까지 녹이는 치주염으로 진행됩니다. 스케일링 후 일시적으로 이가 시리거나 치아 사이가 벌어진 느낌이 들 수 있는데, 이는 치석이 차지하던 공간이 드러나고 부었던 잇몸이 가라앉으며 나타나는 자연스러운 회복 과정입니다. 만 19세 이상은 연 1회 건강보험이 적용되어 본인부담금이 낮으며, 잇몸 상태에 따라 6개월~1년 간격의 정기적인 스케일링이 권장됩니다. 스케일링만으로 해결되지 않는 깊은 치석은 치근활택술 등 추가 잇몸치료가 필요할 수 있습니다.', related: 'gum' },
  { term: '레진', reading: 'Resin', category: '치료·시술', def: '충치를 제거한 자리나 깨진 부위를 치아 색과 유사한 복합 레진으로 직접 메우는 치료입니다. 페이스트 형태의 재료를 충치를 제거한 자리에 층층이 채우고 특수 광선으로 굳히는 방식이라, 본을 뜨는 과정 없이 대부분 당일 한 번의 내원으로 치료가 끝납니다. 치아 색과 거의 구분되지 않을 만큼 심미성이 좋고, 아말감이나 금속 재료에 비해 치아 삭제량이 적어 건강한 치아 조직을 최대한 보존할 수 있다는 장점이 있습니다. 초기~중기 충치, 치아 사이의 작은 충치, 앞니의 깨짐이나 벌어짐 개선 등에 폭넓게 활용됩니다. 다만 충치 범위가 크거나 씹는 힘을 많이 받는 부위에는 강도가 부족할 수 있어, 이런 경우에는 인레이나 크라운이 더 적합합니다. 시간이 지나면 변색되거나 가장자리가 마모될 수 있으므로 정기검진에서 상태를 확인하고 필요시 보수하는 것이 좋습니다.', related: 'cavity' },
  { term: '인레이·온레이', reading: 'Inlay / Onlay', category: '치료·시술', def: '충치 범위가 커서 레진으로 직접 메우기 어려울 때, 치아 본을 떠서 기공소에서 맞춤 제작한 수복물을 치아에 접착하는 치료입니다. 수복물이 치아 씹는 면의 홈 안에 들어가면 인레이, 씹는 면의 봉우리(교두)까지 덮으면 온레이라고 부릅니다. 입안에서 직접 굳히는 레진과 달리 외부에서 정밀하게 제작해 강도와 맞음새가 우수하고, 치아 사이 접촉면까지 정확하게 회복할 수 있습니다. 재료는 심미성이 좋은 세라믹(도재), 강도와 적합도가 검증된 골드 등이 있으며 위치와 씹는 힘을 고려해 선택합니다. 크라운처럼 치아 전체를 깎지 않고 손상 부위만 최소로 삭제한다는 점에서 치아 보존에 유리한 중간 단계의 치료입니다. 통상 두 번의 내원(치아 형성·본뜨기, 접착)으로 완료되며, 접착 후에는 자연치아와 동일하게 사용하되 지나치게 단단한 음식은 주의하는 것이 좋습니다.', related: 'cavity' },
  { term: '치아미백', reading: 'Whitening', category: '치료·시술', def: '과산화수소 계열의 전용 약제로 치아 내부와 표면에 스며든 착색 물질을 분해해 치아를 본래보다 밝은 색으로 만드는 시술입니다. 커피, 와인, 흡연 등으로 서서히 어두워진 치아나 나이가 들며 노랗게 변한 치아에 효과적입니다. 치과에서 고농도 약제와 광선을 이용해 짧은 기간에 밝히는 전문가 미백과, 맞춤 트레이에 저농도 약제를 담아 집에서 착용하는 자가 미백이 있으며 두 가지를 병행하면 효과가 더 오래 유지됩니다. 시술 후 일시적으로 이가 시릴 수 있으나 대부분 며칠 내 사라집니다. 미백 직후에는 착색이 잘 되는 커피, 카레, 콜라 등을 피하는 것이 좋고, 효과는 관리 습관에 따라 1~3년 유지되며 필요시 추가 미백으로 톤을 되살릴 수 있습니다. 다만 레진, 크라운 같은 보철물은 미백약제로 색이 변하지 않으므로, 앞니에 보철물이 있는 경우 시술 전 상담이 필요합니다.', related: 'aesthetic' },
  { term: '잇몸이식술', reading: 'Gum Graft', category: '치료·시술', def: '잇몸 퇴축으로 치아 뿌리가 드러난 부위에 입천장 등에서 채취한 결합조직이나 잇몸 조직을 이식해 부족한 잇몸을 회복시키는 수술입니다. 잇몸이 내려앉으면 치아가 길어 보여 심미적으로 좋지 않을 뿐 아니라, 노출된 뿌리 표면은 법랑질이 없어 시린 증상과 충치(치근우식)에 취약해집니다. 잇몸이식은 이런 노출 부위를 덮어 시린 증상을 줄이고, 얇은 잇몸을 두껍게 만들어 추가 퇴축을 예방하는 효과가 있습니다. 잘못된 칫솔질 습관, 치주염, 교정 치료 후 얇아진 잇몸 등이 주요 원인이므로 수술과 함께 원인 교정이 반드시 병행되어야 합니다. 수술은 국소마취로 진행되며 회복에는 통상 2~3주가 걸립니다. 이식 부위가 안정될 때까지는 해당 부위 칫솔질을 피하고 처방된 가글로 관리하며, 금연과 부드러운 식사가 회복 속도를 크게 좌우합니다.', related: 'gum' },
  { term: '뼈이식', reading: 'Bone Graft', category: '치료·시술', def: '임플란트를 심기에 잇몸뼈의 폭이나 높이가 부족할 때, 골이식재를 이용해 뼈를 보강하는 술식입니다. 치아를 상실한 뒤 오래 방치하면 씹는 자극이 사라진 잇몸뼈가 점점 흡수되어, 임플란트를 고정할 뼈 자체가 모자라게 됩니다. 이때 자가골(본인 뼈), 동종골, 이종골, 합성골 등의 이식재를 부족한 부위에 채우고 필요시 차폐막으로 덮어 새 뼈가 자라날 공간을 확보합니다. 위쪽 어금니 부위에서 상악동 공간 때문에 뼈 높이가 부족할 때 시행하는 상악동거상술도 뼈이식의 대표적인 형태입니다. 이식한 뼈가 단단하게 자리 잡기까지는 통상 3~6개월이 걸리며, 뼈 상태에 따라 임플란트 식립과 동시에 진행하기도 하고 뼈가 아문 뒤 식립하기도 합니다. 수술 후 부기와 멍이 있을 수 있으나 대부분 1~2주 내 가라앉으며, 금연이 성공률에 매우 중요합니다.', related: 'implant' },
  { term: '보톡스(치과)', reading: 'Dental Botox', category: '치료·시술', def: '보툴리눔 톡신을 저작근(깨물근)이나 측두근에 주사해 과도하게 발달하거나 긴장된 근육의 힘을 일시적으로 줄여주는 시술입니다. 치과에서는 미용 목적보다 기능적 치료로 활용되는 경우가 많습니다. 이갈이나 이 악물기 습관이 심한 분은 저작근이 지나치게 발달해 치아 마모, 균열, 턱관절 통증으로 이어질 수 있는데, 보톡스로 근육의 힘을 조절하면 치아와 턱관절이 받는 부담을 크게 줄일 수 있습니다. 부수적으로 발달한 저작근이 줄며 사각턱이 갸름해지는 윤곽 개선 효과도 있습니다. 시술은 주사만으로 5~10분 내에 끝나고 일상생활에 지장이 거의 없으며, 효과는 시술 후 1~2주부터 나타나 통상 3~6개월 유지됩니다. 반복 시술 시 효과가 더 오래가는 경향이 있습니다. 임신·수유 중이거나 신경근육 질환이 있는 경우는 시술 전 반드시 알려야 합니다.', related: 'botox' },
  { term: '치수', reading: 'Dental Pulp', category: '구조·해부', def: '치아의 가장 안쪽에 있는 신경과 혈관, 세포로 이루어진 살아있는 조직입니다. 흔히 치아 신경이라고 부르는 부분으로, 치아에 영양을 공급하고 뜨거움·차가움·통증 같은 감각을 느끼게 하며, 세균 침입에 대한 방어 반응도 담당합니다. 치아 머리 부분의 치수는 치수강에, 뿌리 부분의 치수는 가느다란 근관 속에 들어 있습니다. 충치가 법랑질과 상아질을 지나 치수까지 도달하면 세균 감염으로 치수염이 생기는데, 초기에는 찬 것에 시린 정도지만 진행되면 가만히 있어도 욱신거리고 밤에 더 심해지는 특징적인 통증이 나타납니다. 한 번 감염된 치수는 저절로 회복되기 어려워 신경치료로 제거해야 하는 경우가 대부분입니다. 치수가 건강해야 치아가 수분과 영양을 유지해 잘 깨지지 않으므로, 치수를 지키는 최선의 방법은 충치를 초기에 발견해 치료하는 정기검진입니다.', related: 'endo' },
  { term: '법랑질', reading: 'Enamel', category: '구조·해부', def: '치아의 가장 바깥을 덮고 있는 반투명한 보호층으로, 96%가 무기질로 이루어져 인체에서 가장 단단한 조직입니다. 뼈보다 단단해 수십 년간의 저작 활동을 견뎌내지만, 두 가지 결정적인 약점이 있습니다. 첫째, 산에 약합니다. 충치균이 당분을 분해하며 만드는 산이나 탄산음료·과일주스의 산성 성분이 법랑질의 미네랄을 녹입니다(탈회). 둘째, 세포가 없어 한 번 손상되면 피부나 뼈처럼 재생되지 않습니다. 초기 탈회 단계에서는 침과 불소의 도움으로 미네랄이 다시 채워질 수 있지만(재광화), 구멍이 생긴 뒤에는 치과 치료로만 회복이 가능합니다. 법랑질이 마모되거나 얇아지면 속의 노란 상아질이 비쳐 치아가 어두워 보이고 시린 증상도 생깁니다. 법랑질을 지키려면 산성 음료 섭취 후 30분 뒤 양치하기, 불소치약 사용, 과도한 힘으로 이 악물지 않기가 중요합니다.' },
  { term: '상아질', reading: 'Dentin', category: '구조·해부', def: '법랑질 안쪽에서 치아의 대부분을 이루는 노란빛의 조직입니다. 법랑질보다는 무르지만 뼈와 비슷한 강도를 가지며, 치아의 형태와 탄력을 유지하는 몸통 역할을 합니다. 상아질에는 상아세관이라는 미세한 관이 무수히 지나가는데, 이 관들이 치아 중심의 신경(치수)과 연결되어 있습니다. 그래서 법랑질이 마모되거나 잇몸이 내려가 상아질이 입안에 노출되면, 찬물·단것·칫솔 자극이 상아세관을 타고 신경까지 전달되어 시린 증상(지각과민)이 나타납니다. 충치가 상아질까지 진행되면 법랑질에서보다 훨씬 빠른 속도로 퍼지는 것도 특징입니다. 상아질은 법랑질과 달리 치수의 세포가 살아있는 동안 방어성 상아질을 조금씩 새로 만들 수 있지만, 그 속도가 충치 진행을 따라가지는 못합니다. 시린 증상이 2주 이상 계속된다면 단순 지각과민인지 충치·균열인지 감별 진단이 필요합니다.' },
  { term: '치조골', reading: 'Alveolar Bone', category: '구조·해부', def: '치아 뿌리를 감싸 치아를 단단히 지지하는 턱뼈 부분으로, 흔히 잇몸뼈라고 부릅니다. 치아는 치조골에 직접 붙어 있는 것이 아니라 치주인대라는 얇은 섬유조직을 사이에 두고 매달려 있어, 씹을 때의 충격이 자연스럽게 분산됩니다. 치조골은 치아가 있어야 유지되는 특성이 있습니다. 치아를 뽑고 오래 방치하면 씹는 자극이 사라진 부위의 뼈가 점점 흡수되어 높이와 폭이 줄어들고, 나중에 임플란트를 하려면 뼈이식이 필요해지는 경우가 많습니다. 치주염도 치조골의 큰 적입니다. 치석 속 세균이 일으킨 염증이 치조골을 서서히 녹이면 치아가 흔들리기 시작하는데, 한 번 녹은 뼈는 저절로 회복되지 않습니다. 치아 상실 후에는 가급적 빨리 임플란트 등으로 수복하고, 잇몸이 붓거나 피가 나는 초기 신호 단계에서 잇몸치료를 받는 것이 치조골을 지키는 핵심입니다.', related: 'implant' },
  { term: '치근', reading: 'Root', category: '구조·해부', def: '잇몸 속 치조골에 묻혀 치아를 지탱하는 뿌리 부분입니다. 눈에 보이는 치아 머리(치관)가 빙산의 일각이라면, 치근은 물밑에서 전체를 받치는 몸체에 해당합니다. 앞니는 보통 1개, 작은어금니는 1~2개, 큰어금니는 2~3개의 치근을 가지며, 뿌리가 많고 길수록 씹는 힘을 잘 견딥니다. 치근 표면은 법랑질이 아닌 백악질이라는 얇은 조직으로 덮여 있고, 그 위에 치주인대가 붙어 치조골과 연결됩니다. 잇몸이 내려앉아 치근이 입안에 노출되면 백악질이 쉽게 닳아 시린 증상이 생기고, 법랑질보다 산에 약해 치근 충치가 빠르게 진행됩니다. 특히 장년층 충치의 상당수가 치근 부위에서 발생합니다. 또 치근 끝에는 신경과 혈관이 드나드는 구멍이 있어, 치수 감염이 이 통로를 넘어가면 뿌리 끝 염증(치근단 병소)으로 번질 수 있습니다. 치근을 지키는 기본은 잇몸 건강 관리입니다.' },
  { term: '턱관절(악관절)', reading: 'TMJ', category: '구조·해부', def: '아래턱뼈와 머리뼈(측두골)를 연결하는 관절로, 귀 바로 앞에 좌우 하나씩 위치합니다. 말하기, 씹기, 하품 등 하루 수천 번 움직이는, 우리 몸에서 가장 자주 사용되는 관절 중 하나입니다. 관절 사이에는 디스크(관절원판)라는 쿠션 조직이 있어 뼈끼리 부딪히지 않도록 완충 역할을 하는데, 이 디스크가 제자리를 벗어나거나 주변 근육에 문제가 생기면 턱관절 장애가 나타납니다. 입을 벌릴 때 딸깍 소리가 나거나, 턱이 걸려 잘 벌어지지 않거나, 귀 앞·관자놀이 통증과 두통이 대표 증상입니다. 좌우 관절이 하나의 아래턱뼈로 연결되어 항상 함께 움직이기 때문에 한쪽에만 문제가 생겨도 반대쪽까지 영향을 받기 쉽습니다. 딱딱하고 질긴 음식, 이갈이, 한쪽으로만 씹는 습관, 턱 괴기, 스트레스가 주요 악화 요인이므로 생활 습관 교정이 치료의 중요한 축입니다.', related: 'tmj' },
  { term: '사랑니(제3대구치)', reading: 'Wisdom Tooth', category: '구조·해부', def: '구강 가장 안쪽에 마지막으로 나는 세 번째 큰어금니로, 보통 10대 후반~20대에 맹출합니다. 현대인은 턱이 작아지는 방향으로 진화해 사랑니가 나올 공간이 부족한 경우가 많고, 그 결과 옆으로 눕거나 비스듬히 매복된 채 일부만 드러나는 일이 흔합니다. 문제는 위치입니다. 칫솔이 닿기 어려운 가장 안쪽에 있어 청결 관리가 힘들고, 잇몸에 반쯤 덮인 사랑니 주변은 세균이 고이기 좋아 붓고 아픈 지치주위염이 반복되기 쉽습니다. 누워서 난 사랑니는 바로 앞 어금니를 밀거나 그 사이에 충치를 만들어 멀쩡한 치아까지 망가뜨릴 수 있습니다. 반듯하게 나서 잘 닦이는 사랑니는 뽑지 않아도 되지만, 염증·충치·앞니 손상 위험이 있는 경우 발치가 권장됩니다. 아래 사랑니는 신경관과 가까운 경우가 있어, 발치 전 CT로 신경 위치를 확인하면 훨씬 안전합니다.', related: 'wisdom' },
  { term: '지르코니아', reading: 'Zirconia', category: '재료·장비', def: '인공 다이아몬드 소재로도 알려진 지르코늄 산화물을 치과용으로 가공한 세라믹 계열 보철 재료입니다. 현재 크라운과 임플란트 보철에서 가장 널리 쓰이는 재료로, 금속에 버금가는 강도와 세라믹의 심미성을 동시에 갖췄습니다. 과거의 금속-도재 크라운(PFM)은 속의 금속이 비쳐 잇몸 경계가 검게 보이는 문제가 있었지만, 지르코니아는 금속을 전혀 쓰지 않아 잇몸 변색이 없고 빛 투과성이 자연치아와 유사합니다. 금속 알레르기 걱정이 없다는 것도 장점입니다. 강도가 높아 씹는 힘이 강한 어금니에도 안심하고 사용할 수 있으며, 기술 발전으로 투명도를 높인 심미형 지르코니아는 앞니에도 자연스러운 결과를 냅니다. CAD/CAM 디지털 장비로 정밀하게 깎아 제작하므로 맞음새도 우수합니다. 다만 매우 단단한 만큼 맞물리는 자연치아의 마모를 줄이기 위한 정밀한 교합 조정과 표면 연마가 중요합니다.', related: 'prosthetics' },
  { term: '티타늄', reading: 'Titanium', category: '재료·장비', def: '임플란트 인공치근의 표준 재료로 쓰이는 금속입니다. 가볍고 강하며 부식에 강하다는 물리적 장점도 있지만, 치과에서 티타늄이 특별한 진짜 이유는 골유착이라는 독특한 성질 때문입니다. 1950년대 스웨덴의 브로네마르크 교수가 토끼 뼈에 넣은 티타늄 장치가 뼈와 단단히 붙어 분리되지 않는 현상을 발견했고, 이것이 현대 임플란트의 출발점이 되었습니다. 티타늄 표면은 산소와 만나 안정된 산화막을 형성하는데, 이 막 덕분에 몸이 티타늄을 이물질로 거부하지 않고 뼈세포가 표면에 직접 붙어 자랍니다. 인공관절, 심장 스텐트에도 쓰일 만큼 생체 친화성이 검증된 재료입니다. 최근 임플란트는 티타늄 표면을 미세하게 거칠게 처리해 뼈와 닿는 면적을 넓히는 방향으로 발전해 골유착 속도와 안정성이 크게 향상되었습니다. 금속 알레르기 반응도 극히 드물어 안전성이 높습니다.', related: 'implant' },
  { term: '미세현미경', reading: 'Dental Microscope', category: '재료·장비', def: '치료 부위를 최대 수십 배까지 확대해 밝은 조명 아래에서 보며 치료할 수 있게 해주는 정밀 진료 장비입니다. 사람 눈으로 구분할 수 있는 한계는 약 0.2mm인데, 신경치료에서 다뤄야 하는 근관 입구나 치아의 미세 균열은 그보다 작은 경우가 많습니다. 미세현미경을 사용하면 육안으로 놓치기 쉬운 숨은 근관(MB2 등), 막힌 근관, 머리카락보다 가는 균열선까지 직접 눈으로 확인하며 치료할 수 있어 신경치료의 성공률이 크게 올라갑니다. 특히 이전 신경치료가 실패해 다시 치료하는 재신경치료, 원인을 알 수 없는 통증의 균열 진단, 부러진 기구 제거 같은 난이도 높은 치료에서 진가를 발휘합니다. 확대 시야에서는 필요한 만큼만 정확히 삭제할 수 있어 건강한 치아 조직 보존에도 유리합니다. 치아를 살릴 수 있는 마지막 기회를 잡아주는 장비라고 할 수 있습니다.', related: 'endo' },
  { term: 'CT(콘빔CT)', reading: 'CBCT', category: '재료·장비', def: '치아와 턱뼈를 3차원 입체 영상으로 촬영하는 치과 전용 장비입니다. 일반 엑스레이(파노라마)가 입체 구조를 한 장의 평면에 겹쳐 보여주는 반면, CT는 뼈의 폭·높이·밀도, 신경관의 정확한 위치, 상악동의 형태까지 mm 단위로 파악할 수 있습니다. 임플란트 식립 전에 CT로 신경관까지의 거리와 뼈 폭을 확인하면 신경 손상 위험을 크게 줄일 수 있고, 매복 사랑니 발치 전에는 뿌리와 신경관의 관계를 미리 확인해 안전한 발치 계획을 세울 수 있습니다. 신경치료에서도 복잡한 근관 형태나 뿌리 끝 염증의 정확한 위치·크기를 진단하는 데 활용됩니다. 치과용 콘빔CT는 의료용 CT보다 방사선량이 현저히 적고 촬영도 10~20초면 끝납니다. 정밀 진단이 정확한 치료 계획의 출발점인 만큼, 수술적 치료 전 CT 촬영은 안전을 위한 필수 과정으로 자리 잡았습니다.', related: 'implant' },
  { term: '구강스캐너', reading: 'Intraoral Scanner', category: '재료·장비', def: '작은 카메라가 달린 스캐너를 입안에 넣어 치아와 잇몸을 3차원 디지털 데이터로 촬영하는 장비입니다. 전통적인 본뜨기는 말랑한 인상재를 담은 트레이를 입에 물고 굳을 때까지 기다려야 해서 구역감이 심한 분들에게 큰 고역이었는데, 구강스캐너는 입안을 카메라로 훑기만 하면 몇 분 만에 정밀한 디지털 모형이 완성됩니다. 구역감이 없을 뿐 아니라, 인상재가 굳는 과정에서 생기는 변형이나 석고 모형 제작 단계의 오차가 없어 정밀도도 우수합니다. 스캔 데이터는 즉시 화면에서 확인할 수 있어 부족한 부분만 다시 스캔하면 되고, 기공소로 파일이 바로 전송되어 보철물 제작 기간도 단축됩니다. 크라운, 인레이, 라미네이트 제작은 물론 임플란트 디지털 가이드 설계, 교정 진단까지 활용 범위가 넓습니다. 디지털 치과 진료의 출발점이 되는 장비입니다.' },
  { term: '디지털 가이드', reading: 'Surgical Guide', category: '재료·장비', def: 'CT의 뼈 정보와 구강스캐너의 치아·잇몸 정보를 컴퓨터에서 결합해, 임플란트가 들어갈 최적의 위치·깊이·각도를 수술 전에 미리 설계하고, 그 설계를 실제 수술에서 그대로 재현하도록 유도하는 맞춤 장치입니다. 마우스피스처럼 치아에 걸어 고정하면 가이드에 뚫린 구멍이 드릴의 경로를 정확히 안내해, 계획한 위치에서 벗어나지 않게 잡아줍니다. 신경관이나 상악동 같은 중요 구조물을 피해서 설계하므로 안전성이 높고, 잇몸을 크게 절개하지 않는 최소 절개 수술이 가능해 출혈과 부기가 적고 회복이 빠릅니다. 뼈 상태가 좋은 경우 수술 시간도 크게 단축됩니다. 특히 여러 개를 동시에 심는 수술이나 뼈 폭이 좁아 오차 여유가 적은 부위에서 정밀도의 가치가 커집니다. 수술의 성패를 감에 의존하지 않고 데이터와 설계로 미리 결정해 두는 디지털 임플란트의 핵심 도구입니다.', related: 'implant' },
  { term: '충치(치아우식증)', reading: 'Dental Caries', category: '증상·질환', def: '입안 세균이 음식물 속 당분을 분해하며 만든 산이 치아의 미네랄을 녹여 치아가 썩는 질환입니다. 감기 다음으로 흔한 질병으로 불릴 만큼 유병률이 높습니다. 진행 단계에 따라 치료가 완전히 달라집니다. 법랑질에 국한된 초기에는 통증이 전혀 없고 하얀 반점 정도로만 보이며, 이 단계에서 발견하면 불소도포나 간단한 레진으로 끝납니다. 상아질까지 진행되면 차고 단 것에 시리기 시작하고 진행 속도도 빨라지며, 신경(치수)까지 도달하면 극심한 통증과 함께 신경치료가 필요해집니다. 더 방치해 뿌리 끝 염증과 파괴가 심해지면 발치 후 임플란트까지 가게 됩니다. 문제는 통증이 느껴질 때는 이미 상당히 진행된 뒤라는 점입니다. 충치는 조기 발견이 치료 범위와 비용을 좌우하는 대표적인 질환이므로, 증상이 없어도 6개월~1년 간격의 정기검진이 최선의 예방책입니다.', related: 'cavity' },
  { term: '치주염', reading: 'Periodontitis', category: '증상·질환', def: '치석 속 세균이 일으킨 염증이 잇몸을 넘어 치아를 지지하는 치조골까지 파괴하는 질환으로, 성인 치아 상실의 가장 큰 원인입니다. 잇몸에만 염증이 있는 치은염 단계에서는 회복이 가능하지만, 치주염으로 진행되면 잇몸과 치아 사이가 벌어져 깊은 주머니(치주낭)가 생기고 그 속에서 세균이 뼈를 서서히 녹입니다. 한 번 녹은 뼈는 저절로 재생되지 않습니다. 무서운 점은 진행 과정에 통증이 거의 없다는 것입니다. 잇몸에서 피가 나고, 입냄새가 심해지고, 잇몸이 내려앉고, 치아가 흔들리는 순서로 진행되는데 흔들림을 느낄 때면 이미 뼈의 상당 부분이 소실된 경우가 많습니다. 침묵의 질환이라 불리는 이유입니다. 치료는 진행 정도에 따라 스케일링, 치근활택술, 잇몸 수술로 나뉘며, 당뇨·심혈관 질환과의 연관성도 보고되어 있어 전신 건강 차원에서도 관리가 중요합니다.', related: 'gum' },
  { term: '치은염', reading: 'Gingivitis', category: '증상·질환', def: '염증이 잇몸(치은)에만 국한된 잇몸 질환의 초기 단계입니다. 양치할 때 피가 나고, 잇몸이 빨갛게 붓고, 살짝 눌러도 아픈 것이 대표 증상입니다. 원인은 치아와 잇몸 경계에 쌓인 세균막(플라크)과 치석입니다. 치은염의 가장 중요한 특징은 되돌릴 수 있다는 점입니다. 아직 치조골 손상이 없는 단계이므로, 스케일링으로 치석을 제거하고 올바른 칫솔질과 치실 사용을 병행하면 잇몸이 건강한 상태로 완전히 회복됩니다. 하지만 피가 난다고 그 부위를 살살 닦거나 피하면 플라크가 더 쌓여 악화되고, 방치하면 뼈를 녹이는 치주염으로 진행됩니다. 치주염이 되면 파괴된 뼈를 되돌릴 수 없으므로, 치은염 단계가 잇몸을 지킬 수 있는 결정적 시기입니다. 잇몸 출혈은 몸이 보내는 조기 경고 신호이니, 2주 이상 계속되면 치과 검진을 받아보는 것이 좋습니다.', related: 'gum' },
  { term: '치아균열증후군', reading: 'Cracked Tooth', category: '증상·질환', def: '치아에 눈에 잘 보이지 않는 미세한 금이 가서 씹을 때 찌릿한 통증이 나타나는 질환입니다. 특정 부위로 씹을 때만 순간적으로 아프고 평소에는 멀쩡한 경우가 많으며, 엑스레이에도 잘 나타나지 않아 진단이 까다로운 질환으로 꼽힙니다. 딱딱한 음식(얼음, 마른오징어, 견과류)을 즐기는 습관, 이갈이, 큰 충전물로 약해진 치아가 주요 원인이며, 한국인은 질긴 음식 문화 탓에 발생률이 높은 편입니다. 균열은 스스로 아물지 않고 씹을 때마다 조금씩 진행됩니다. 초기에 발견하면 크라운으로 감싸 진행을 막을 수 있지만, 균열이 신경까지 닿으면 신경치료가 필요하고, 뿌리까지 쪼개지면 발치 외에 방법이 없습니다. 진단에는 특정 치아를 물어보는 검사, 염색, 미세현미경 관찰이 활용됩니다. 씹을 때만 반복되는 찌릿함이 있다면 빨리 검진을 받는 것이 치아를 살리는 길입니다.', related: 'endo' },
  { term: '턱관절 장애', reading: 'TMD', category: '증상·질환', def: '턱관절과 주변 저작 근육의 기능에 문제가 생긴 상태를 통칭하는 질환입니다. 입을 벌리거나 다물 때 딸깍·모래 갈리는 소리, 귀 앞 통증, 입이 잘 안 벌어지는 개구장애가 3대 증상이며, 두통·목과 어깨 결림·귀 먹먹함처럼 턱과 무관해 보이는 증상으로 나타나기도 합니다. 원인은 하나가 아니라 이갈이, 이 악물기, 딱딱한 음식 선호, 한쪽으로만 씹기, 턱 괴기, 스트레스로 인한 근육 긴장 등이 복합적으로 작용합니다. 치료는 대부분 수술이 아닌 보존적 방법으로 시작합니다. 원인 습관을 교정하는 행동요법, 수면 중 착용해 관절 부담을 줄이는 교합안정장치(스플린트), 물리치료와 약물치료가 기본이며, 근육성 문제에는 보톡스가 효과적인 경우도 있습니다. 초기에 관리하면 예후가 좋지만 방치해 디스크 변형이 굳어지면 회복이 어려워지므로, 소리·통증이 2주 이상 지속되면 진단을 받아보시길 권합니다.', related: 'tmj' },
  { term: '이갈이(브럭시즘)', reading: 'Bruxism', category: '증상·질환', def: '수면 중이나 집중할 때 무의식적으로 이를 갈거나 꽉 무는 습관입니다. 본인은 모르는 채 가족의 말이나 치과 검진에서 발견되는 경우가 대부분입니다. 문제는 그 힘의 크기입니다. 수면 중 이갈이는 의식적으로 씹을 때보다 몇 배 강한 힘이 치아에 가해져, 치아가 평평하게 닳고(교모), 잇몸 근처가 패이고, 균열이 생기며, 크라운·임플란트 보철물이 깨지는 원인이 됩니다. 아침에 턱이 뻐근하거나 관자놀이가 아픈 것도 밤새 근육이 혹사당했다는 신호입니다. 장기적으로는 턱관절 장애와 사각턱(저작근 비대)으로 이어질 수 있습니다. 완전히 없애는 치료법은 아직 없지만, 수면 중 나이트가드를 착용해 치아를 보호하고, 저작근 보톡스로 무는 힘 자체를 줄이는 방법이 효과적입니다. 스트레스 관리와 카페인·음주 줄이기도 도움이 됩니다. 치아 마모가 보이기 시작했다면 더 늦기 전에 보호 장치를 시작하는 것이 좋습니다.', related: 'botox' },
  { term: '지각과민증', reading: 'Hypersensitivity', category: '증상·질환', def: '찬물, 단 음식, 칫솔질, 찬 바람 같은 자극에 치아가 순간적으로 시리고 찌릿한 증상입니다. 충치가 없는데도 시리다면 대부분 상아질 노출이 원인입니다. 잇몸이 내려앉아 뿌리가 드러났거나, 과도한 옆 방향 칫솔질로 치아 목 부분이 패였거나(치경부 마모), 이갈이로 법랑질이 닳으면 속의 상아질이 노출되고, 상아세관을 통해 자극이 신경까지 전달되어 시림을 느낍니다. 치료는 원인과 정도에 따라 다릅니다. 가벼운 경우 시린이 전용 치약(질산칼륨 성분)을 꾸준히 쓰면 호전되고, 치과에서 노출 부위에 지각과민 처치제를 바르거나 패인 부위를 레진으로 메우기도 합니다. 잇몸 퇴축이 심하면 잇몸이식을 고려합니다. 다만 시림은 충치, 균열, 치수염의 초기 신호일 수도 있으므로 자가 판단은 금물입니다. 2주 이상 지속되거나 점점 심해지는 시림은 감별 진단이 필요합니다.', related: 'gum' },
  { term: '치실·치간칫솔', reading: 'Floss / Interdental Brush', category: '예방·관리', def: '칫솔이 닿지 않는 치아 사이 면을 닦는 필수 구강관리 도구입니다. 아무리 꼼꼼히 칫솔질을 해도 칫솔모는 치아 사이 인접면에 닿지 않아, 전체 치아 면적의 약 30%는 그대로 남습니다. 실제로 충치와 잇몸 질환이 가장 많이 시작되는 곳이 바로 이 치아 사이입니다. 치실은 치아 사이 틈이 좁은 젊은 층이나 앞니에 적합하고, 치간칫솔은 잇몸이 살짝 내려앉아 공간이 생긴 중장년층이나 어금니, 임플란트·브릿지 주변에 효과적입니다. 치간칫솔은 억지로 밀어 넣지 말고 저항 없이 들어가는 가장 큰 사이즈를 고르는 것이 요령입니다. 처음 사용할 때 피가 나는 것은 이미 잇몸에 염증이 있다는 신호로, 꾸준히 사용하면 1~2주 내 출혈이 줄어듭니다. 하루 한 번, 잠들기 전 칫솔질 전에 사용하는 습관만 들여도 충치와 치주 질환 예방 효과가 크게 올라갑니다.', related: 'gum' },
  { term: '불소도포', reading: 'Fluoride Application', category: '예방·관리', def: '고농도 불소를 치아 표면에 발라 법랑질을 강화하고 충치를 예방하는 처치입니다. 불소는 치아의 주성분인 수산화인회석과 결합해 산에 훨씬 강한 불화인회석 구조를 만들고, 세균이 산을 만드는 활동 자체도 억제합니다. 특히 산에 살짝 녹기 시작한 초기 충치(하얀 반점 단계)에서는 녹아 나간 미네랄을 다시 채워 넣는 재광화를 도와, 충치를 갈아내지 않고 되돌릴 수 있는 기회를 줍니다. 치과에서는 바니시나 젤 형태의 전문가용 불소를 치아에 바르며, 시간은 몇 분이면 충분하고 통증도 없습니다. 법랑질이 약한 어린이, 교정장치 착용자, 잇몸 퇴축으로 뿌리가 노출된 중장년층, 입이 마르는 분들에게 특히 효과적이며 3~6개월 간격의 정기 도포를 권합니다. 가정에서는 불소 함유 치약(1,000ppm 이상)을 쓰고 양치 후 물로 과하게 헹구지 않는 것이 도포 효과를 이어가는 방법입니다.', related: 'cavity' },
  { term: '정기검진', reading: 'Regular Check-up', category: '예방·관리', def: '증상이 없어도 6개월~1년 간격으로 치아와 잇몸 상태를 점검하는 예방 진료입니다. 치과 질환의 특성상 정기검진의 가치는 매우 큽니다. 충치와 치주염은 초기에 통증이 거의 없어, 아파서 치과에 왔을 때는 이미 신경치료나 발치가 필요한 단계인 경우가 많기 때문입니다. 같은 충치라도 초기에 발견하면 간단한 레진으로 몇 만원에 끝나지만, 방치하면 신경치료와 크라운, 나아가 임플란트까지 치료 범위와 비용이 기하급수적으로 커집니다. 검진에서는 충치·잇몸 상태 확인, 필요시 엑스레이 촬영, 스케일링, 구강 위생 교육이 함께 이뤄지며, 잇몸이 약한 분·임플란트 사용자·충치가 잘 생기는 분은 3~4개월 간격을 권하기도 합니다. 건강보험으로 연 1회 스케일링이 적용되므로 검진과 묶어 활용하면 부담도 적습니다. 치과는 아플 때 가는 곳이 아니라 아프기 전에 가는 곳이라는 인식이 치아 수명을 결정합니다.', related: 'cavity' },
  { term: '나이트가드', reading: 'Night Guard', category: '예방·관리', def: '수면 중 이갈이와 이 악물기로부터 치아와 턱관절을 보호하기 위해 밤에 착용하는 맞춤형 장치입니다. 수면 중 이갈이는 의식적으로 씹을 때보다 몇 배 강한 힘을 만들어 치아를 닳게 하고, 균열을 일으키고, 크라운·임플란트 보철물을 깨뜨리는 주범입니다. 나이트가드는 위아래 치아 사이에서 완충재 역할을 해, 갈리는 힘을 장치가 대신 받아내고 턱 근육과 관절의 부담도 줄여줍니다. 치아가 닳는 것을 막을 뿐 아니라 아침 턱 뻐근함과 두통 완화에도 도움이 됩니다. 시중의 기성품도 있지만 개인 치아 본을 떠서 만드는 맞춤형이 유지력과 교합 안정성에서 훨씬 우수하며, 잘못 맞는 기성품은 오히려 교합을 어긋나게 할 수 있습니다. 처음에는 이물감이 있지만 대부분 1~2주 내 적응합니다. 사용 후에는 찬물로 세척해 건조 보관하고, 마모 상태에 따라 수년 주기로 교체합니다. 이갈이가 있다면 치아가 닳기 전에 시작하는 것이 좋습니다.', related: 'tmj' },
  { term: '임플란트 유지관리', reading: 'Implant Maintenance', category: '예방·관리', def: '임플란트를 오래 쓰기 위해 반드시 필요한 정기 점검과 청결 관리를 말합니다. 임플란트는 충치가 생기지 않아 관리가 필요 없다고 오해하기 쉽지만, 실제로는 자연치보다 세균에 더 취약한 면이 있습니다. 자연치는 치주인대가 세균 방어와 조기 경고(통증) 역할을 하는 반면, 임플란트는 이 구조가 없어 염증이 생겨도 통증 없이 조용히 진행되고, 뼈가 녹는 임플란트 주위염으로 발전하면 진행 속도도 빠릅니다. 관리의 핵심은 두 가지입니다. 첫째, 집에서 임플란트 주변을 치간칫솔과 치실로 매일 꼼꼼히 닦아 세균막을 없애는 것. 둘째, 3~6개월 간격으로 치과를 방문해 잇몸 상태 점검, 전용 기구 스케일링, 나사 풀림·보철물 상태 확인을 받는 것입니다. 이갈이가 있다면 나이트가드로 과도한 힘도 막아야 합니다. 심는 것은 치료의 끝이 아니라 시작이며, 관리 여부가 임플란트 수명을 10년 이상 좌우합니다.', related: 'implant' },
  { term: '발치', reading: 'Tooth Extraction', category: '치료·시술', def: '더 이상 살릴 수 없는 치아를 뽑아내는 치료입니다. 치과 치료의 대원칙은 자연치를 최대한 살리는 것이지만, 심한 치주염으로 뼈 지지가 거의 남지 않은 치아, 뿌리까지 세로로 쪼개진 치아, 신경치료로도 해결되지 않는 뿌리 끝 병소, 문제를 일으키는 매복 사랑니 등은 발치가 오히려 주변 치아와 뼈를 지키는 선택이 됩니다. 발치는 국소마취 하에 진행되어 시술 중 통증은 없으며, 단순 발치는 몇 분 내로 끝나고 매복치는 잇몸 절개와 치아 분할이 필요할 수 있습니다. 발치 후에는 거즈를 2시간가량 물어 지혈하고, 빨대 사용·흡연·강한 가글을 피해 혈병(피딱지)이 떨어지지 않게 하는 것이 중요합니다. 혈병이 소실되면 극심한 통증의 드라이소켓이 생길 수 있습니다. 발치한 자리는 방치하면 주변 치아가 쓰러지고 맞물리던 치아가 내려오므로, 상황에 따라 임플란트·브릿지 등 후속 계획을 함께 세우는 것이 좋습니다.', related: 'wisdom' },
  { term: '국소마취', reading: 'Local Anesthesia', category: '치료·시술', def: '치료할 부위의 감각 신경만 일시적으로 차단해 통증 없이 진료받게 하는 마취 방법입니다. 의식은 그대로 유지되며 치료 부위의 통각만 사라집니다. 치아 주변 잇몸에 놓는 침윤마취와, 아래턱 신경 줄기를 차단해 한쪽 턱 전체를 마취하는 전달마취가 대표적입니다. 많은 분이 마취 주사 자체를 무서워하는데, 요즘은 주사 전에 바르는 표면마취 연고로 바늘 느낌을 줄이고, 컴퓨터가 주입 속도를 일정하게 제어하는 무통마취기를 사용해 약물이 들어갈 때의 압통을 크게 낮출 수 있습니다. 마취는 부위와 방법에 따라 2~4시간가량 지속되며, 풀리기 전에는 입술·볼 감각이 없어 씹다가 깨물어도 모를 수 있으므로 식사는 마취가 풀린 뒤에 하는 것이 안전합니다. 심장이 빨리 뛰는 느낌은 마취액 속 혈관수축제의 일시적 반응으로 대부분 곧 가라앉습니다. 복용 중인 약이나 전신 질환이 있다면 마취 전에 꼭 알려주셔야 합니다.' },
  { term: '파노라마', reading: 'Panoramic X-ray', category: '재료·장비', def: '위아래 턱 전체와 모든 치아를 한 장의 사진에 담는 기본 엑스레이 촬영입니다. 장비가 머리 주위를 한 바퀴 돌며 촬영하고, 10초 남짓이면 전체 치아·턱뼈·상악동·턱관절까지 한눈에 볼 수 있는 영상이 완성됩니다. 눈으로 보이지 않는 치아 사이 충치, 잇몸뼈가 녹은 정도, 매복 사랑니의 위치와 방향, 뿌리 끝 염증, 턱뼈 속 물혹까지 확인할 수 있어 첫 내원 시 구강 전체 상태를 파악하는 기본 검사로 쓰입니다. 방사선량은 매우 적어 일상에서 자연적으로 노출되는 수준과 비교해도 부담이 크지 않습니다. 다만 파노라마는 입체 구조를 평면에 펼쳐 담기 때문에 겹침과 왜곡이 있어, 임플란트 식립이나 매복치 발치처럼 mm 단위 정밀함이 필요한 경우에는 3차원 CT를 추가로 촬영합니다. 파노라마로 전체를 훑고 CT로 정밀하게 들여다보는 것이 표준적인 진단 흐름입니다.' },
  // ===== 일일 자동 공개분 (매일 5개씩) =====
  { term: '틀니(의치)', reading: 'Denture', category: '치료·시술', def: '상실된 여러 개의 치아를 대신하는 착탈식 인공 치아 장치입니다. 치아가 하나도 없을 때 잇몸 전체를 덮는 완전틀니와, 남은 치아에 고리를 걸어 고정하는 부분틀니로 나뉩니다. 수술 없이 비교적 짧은 기간에 여러 치아를 회복할 수 있고 비용 부담이 적은 것이 장점이며, 만 65세 이상은 건강보험 적용(7년 주기)도 가능합니다. 다만 잇몸 위에 얹히는 구조라 씹는 힘이 자연치의 20~30% 수준이고, 사용 중 움직임과 이물감이 있으며, 잇몸뼈가 세월에 따라 흡수되면서 주기적인 조정이나 재제작이 필요합니다. 처음에는 발음과 식사에 적응 기간이 필요하고, 매 식사 후 빼서 전용 세정제로 관리해야 합니다. 최근에는 임플란트 2~4개를 심어 틀니를 딸깍 고정하는 임플란트 틀니로 유지력과 씹는 힘을 크게 개선하는 방법이 널리 쓰입니다. 구강 상태와 건강, 예산에 따라 최적의 방식이 달라지므로 정밀 진단 후 결정하는 것이 좋습니다.', related: 'prosthetics' },
  { term: '임플란트 틀니', reading: 'Overdenture', category: '치료·시술', def: '임플란트 2~4개를 잇몸뼈에 심고, 그 위에 틀니를 단추처럼 딸깍 끼워 고정하는 치료입니다. 일반 틀니의 가장 큰 불편인 헐거움과 들뜸을 해결하는 방법으로, 틀니가 임플란트에 기계적으로 고정되므로 식사나 대화 중에 빠질 걱정이 크게 줄고 씹는 힘도 일반 틀니보다 훨씬 강해집니다. 치아 전체를 임플란트로 회복하려면 한 턱에 6~8개 이상 심어야 하지만, 임플란트 틀니는 2~4개로 충분해 수술 부담과 비용을 크게 낮출 수 있습니다. 잇몸뼈가 많이 부족한 분, 전신 건강상 큰 수술이 어려운 분, 기존 틀니의 헐거움으로 고생하신 분에게 특히 좋은 대안입니다. 본인이 쉽게 뺐다 끼울 수 있어 청결 관리도 용이합니다. 다만 연결 부속(어태치먼트)은 소모품이라 주기적 교체가 필요하고, 임플란트 주변 위생 관리와 정기검진은 필수입니다. 전체 임플란트와 일반 틀니 사이의 균형 잡힌 절충안이라 할 수 있습니다.', related: 'implant' },
  { term: '상악동거상술', reading: 'Sinus Lift', category: '치료·시술', def: '위턱 어금니 부위에 임플란트를 심을 뼈 높이가 부족할 때, 상악동(위턱뼈 속 빈 공간) 바닥의 막을 조심스럽게 들어 올리고 그 아래 공간에 뼈이식재를 채워 뼈 높이를 확보하는 수술입니다. 위턱 어금니는 뿌리 바로 위에 상악동이 있는데, 치아를 뽑고 시간이 지나면 잇몸뼈가 흡수되고 상악동은 아래로 커져 임플란트를 심을 뼈가 몇 mm밖에 남지 않는 경우가 흔합니다. 남은 뼈 높이에 따라 방법이 달라집니다. 비교적 뼈가 남아 있으면 임플란트 심을 구멍을 통해 막을 살짝 밀어 올리는 수직접근법으로 식립과 동시에 진행하고, 뼈가 많이 부족하면 옆쪽 벽에 작은 창을 내어 막을 넓게 들어 올리는 측방접근법을 씁니다. 수술 후 코를 세게 풀거나 빨대를 쓰는 행동은 막에 압력을 주므로 몇 주간 피해야 합니다. CT 정밀 진단과 숙련된 술식이 뒷받침되면 위턱 어금니 임플란트의 성공률을 안정적으로 확보할 수 있는 표준 술식입니다.', related: 'implant' },
  { term: '재신경치료', reading: 'Retreatment', category: '치료·시술', def: '과거에 신경치료를 받은 치아에 다시 염증이 생겼을 때, 기존 충전물을 모두 제거하고 근관을 다시 소독·충전하는 치료입니다. 신경치료의 성공률은 높지만, 근관이 워낙 가늘고 복잡해 처음 치료에서 미처 찾지 못한 근관이 남았거나, 소독이 불완전했거나, 크라운 틈으로 세균이 재침투하면 뿌리 끝에 다시 염증이 생길 수 있습니다. 씹을 때 불편감, 잇몸에 생긴 뾰루지(누공), 엑스레이상 뿌리 끝 검은 음영이 대표적인 신호입니다. 재신경치료는 굳어 있는 기존 충전재를 제거하고 숨은 근관을 찾아야 해서 첫 치료보다 난이도가 훨씬 높으며, 미세현미경과 CT가 성공률을 크게 좌우합니다. 현미경으로 확대해 보면 육안으로 보이지 않던 추가 근관, 기구 파절편, 미세 균열을 발견할 수 있기 때문입니다. 재신경치료로도 해결되지 않는 경우 치근단절제술이 다음 선택지가 되며, 이 단계들을 거치면 발치를 피하고 자연치를 살릴 가능성이 열립니다.', related: 'endo' },
  { term: '치근단절제술', reading: 'Apicoectomy', category: '치료·시술', def: '신경치료와 재신경치료로도 뿌리 끝 염증이 낫지 않을 때, 잇몸을 열고 염증 조직과 함께 뿌리 끝 몇 mm를 잘라낸 뒤 절단면을 특수 재료로 밀봉하는 소수술입니다. 발치 전에 자연치를 살리기 위해 시도할 수 있는 마지막 단계의 치료라 할 수 있습니다. 뿌리 끝은 근관이 미세한 가지처럼 갈라져 있어 근관 안쪽에서의 소독만으로는 세균을 완전히 제거하기 어려운 경우가 있는데, 치근단절제술은 문제의 근원인 뿌리 끝 자체를 제거하므로 이런 한계를 해결합니다. 국소마취로 진행되며 수술 시간은 대개 30분~1시간 내외이고, 부기와 불편감은 수일 내 가라앉습니다. 미세현미경을 사용하면 절단면의 미세 균열과 미개척 근관을 확인하며 정밀하게 밀봉할 수 있어 성공률이 종래보다 크게 높아졌습니다. 크라운이나 포스트가 이미 장착되어 위쪽에서 재치료가 어려운 치아에서도, 보철물을 해체하지 않고 뿌리 쪽에서 접근할 수 있다는 장점이 있습니다.', related: 'endo' },
  { term: '잇몸성형술', reading: 'Gingivoplasty', category: '치료·시술', def: '웃을 때 잇몸이 과도하게 드러나거나(거미스마일) 잇몸 라인이 비대칭일 때, 잇몸의 형태를 다듬어 조화로운 미소 선을 만드는 시술입니다. 치아 길이가 유난히 짧아 보이는 경우, 실제로는 치아가 짧은 게 아니라 잇몸이 치아를 과하게 덮고 있는 경우가 많습니다. 이때 잇몸 라인을 정리해 가려져 있던 치관을 드러내면 치아 비율이 살아나고 미소가 달라집니다. 잇몸만 다듬는 경우와, 잇몸 속 뼈 높이까지 함께 조정해야 하는 경우(치관연장술)로 나뉘며, 뼈 조정 없이 잇몸만 자르면 시간이 지나 원래대로 다시 자라 내려올 수 있어 정확한 진단이 중요합니다. 국소마취 하에 레이저나 미세 기구로 진행되고 시술 시간은 부위에 따라 30분 내외, 회복도 빠른 편입니다. 라미네이트나 앞니 보철과 함께 계획하면 치아 형태와 잇몸 라인을 동시에 개선해 완성도를 높일 수 있습니다. 심미 개선뿐 아니라 잇몸이 부어 보이는 만성 염증 조직을 정리하는 목적도 있습니다.', related: 'aesthetic' },
  { term: '치근활택술', reading: 'Root Planing', category: '치료·시술', def: '잇몸 속 치아 뿌리 표면에 붙은 치석과 세균 독소에 오염된 층을 긁어내고 뿌리 면을 매끈하게 다듬는 잇몸 치료입니다. 스케일링이 잇몸 위쪽에 보이는 치석을 제거하는 치료라면, 치근활택술은 잇몸 속 깊은 곳(치주낭)에 숨은 치석까지 제거하는 한 단계 깊은 치료로, 치주염이 진행되어 스케일링만으로 부족할 때 시행합니다. 뿌리 면을 매끄럽게 만드는 이유는 거친 면에는 세균막이 다시 잘 달라붙기 때문이며, 표면이 매끈해지면 잇몸이 뿌리에 다시 밀착되면서 치주낭 깊이가 줄어듭니다. 국소마취 하에 부위를 나누어 여러 번에 걸쳐 진행하는 것이 일반적이고, 치료 후 잇몸이 아물면서 시린 증상이 일시적으로 나타날 수 있으나 대부분 점차 완화됩니다. 이 단계로 해결되지 않는 깊은 부위는 잇몸을 열고 직접 보면서 제거하는 치주수술로 넘어갑니다. 치주염 진행을 막아 발치를 예방하는 중요한 중간 단계 치료입니다.', related: 'gum' },
  { term: '치주수술(잇몸수술)', reading: 'Periodontal Surgery', category: '치료·시술', def: '진행된 치주염에서 스케일링과 치근활택술로 닿지 않는 깊은 치주낭 속 치석과 염증 조직을, 잇몸을 열어 직접 눈으로 확인하며 제거하는 수술적 잇몸 치료입니다. 치주낭이 깊어지면 기구가 바닥까지 닿지 않아 비수술 치료만으로는 한계가 있는데, 잇몸을 젖혀 뿌리와 뼈를 직접 보면서 치석을 남김없이 제거하고, 염증으로 울퉁불퉁해진 뼈 형태를 다듬은 뒤 잇몸을 다시 봉합합니다. 뼈 파괴 형태에 따라서는 뼈이식재나 조직유도재생술을 병행해 소실된 치조골의 일부 재생을 시도하기도 합니다. 국소마취로 진행되고 치료 후 1~2주면 실밥을 제거하며, 잇몸이 아물면서 뿌리가 다소 드러나 시릴 수 있으나 이는 염증 부기가 빠지며 잇몸이 건강한 위치로 자리 잡는 자연스러운 과정입니다. 수술 후에도 정기적인 유지 관리가 뒷받침되어야 효과가 오래갑니다. 흔들리는 치아를 뽑기 전에 살려볼 수 있는 적극적인 치료 수단입니다.', related: 'gum' },
  { term: '임플란트 주위염', reading: 'Peri-implantitis', category: '증상·질환', def: '임플란트 주변 잇몸과 뼈에 세균 염증이 생겨 임플란트를 지지하는 뼈가 녹는 질환으로, 임플란트 실패의 가장 큰 원인입니다. 자연치의 치주염에 해당하지만 더 위험한 면이 있습니다. 자연치는 치주인대가 세균 침입을 막는 방어벽이자 통증이라는 경고 장치 역할을 하는데, 임플란트에는 이 구조가 없어 염증이 저항 없이 빠르게 뼈로 번지고, 상당히 진행될 때까지 아프지 않아 발견이 늦기 쉽습니다. 잇몸이 붓고 피가 나는 초기 단계(주위 점막염)에서는 회복이 가능하지만, 뼈가 녹기 시작하면 진행을 멈추기 위한 치료가 복잡해지고 심하면 임플란트를 제거해야 할 수 있습니다. 원인은 대부분 세균막 축적이며 흡연, 당뇨, 관리되지 않은 치주염 병력이 위험을 높입니다. 예방이 무엇보다 중요하므로, 매일 치간칫솔로 임플란트 주변을 닦고 3~6개월 간격의 정기검진으로 조용한 진행을 조기에 잡아내는 것이 임플란트를 오래 쓰는 핵심입니다.', related: 'implant' },
  { term: '구내염', reading: 'Stomatitis', category: '증상·질환', def: '입안 점막에 생기는 염증을 통칭하며, 흔히 입병이라 부릅니다. 가장 흔한 형태는 하얀 궤양 주위가 빨갛게 둘러싸인 아프타성 구내염으로, 피로·스트레스·수면 부족·영양 불균형(철분, 비타민 B12, 엽산 부족)·점막 상처 등이 유발 요인으로 알려져 있습니다. 대부분 1~2주 안에 저절로 아물며, 그동안 스테로이드 연고나 가글로 통증을 줄이고 자극적인 음식을 피하면 도움이 됩니다. 그 밖에 헤르페스 바이러스에 의한 물집형 구내염, 면역 저하나 틀니 사용자에게 생기는 곰팡이성 구내염(캔디다증) 등 원인이 다양해 양상에 따라 치료가 달라집니다. 주의할 점은 2~3주가 지나도 아물지 않는 궤양입니다. 같은 자리에 오래 지속되는 궤양, 통증 없이 점점 커지는 병변, 하얗거나 붉은 반점이 지워지지 않는 경우는 구강암 감별이 필요하므로 반드시 진료를 받아야 합니다. 입안 상처가 잘 낫는 몸 상태를 만드는 것, 즉 휴식과 영양이 근본 예방책입니다.' },
  { term: '구강건조증', reading: 'Dry Mouth', category: '증상·질환', def: '침 분비가 줄거나 침의 질이 변해 입안이 마르는 증상입니다. 침은 단순한 수분이 아니라 입안의 세균과 산을 씻어내고, 녹은 치아 미네랄을 되돌리고, 점막을 보호하고, 소화를 돕는 다기능 방어 시스템입니다. 그래서 침이 마르면 충치가 급격히 늘고(특히 뿌리 충치), 잇몸 질환과 구내염이 잦아지고, 입냄새가 심해지고, 틀니 사용이 힘들어지는 등 구강 건강 전반이 무너집니다. 원인으로는 고혈압약·항우울제·항히스타민제 등 약물 부작용이 가장 흔하고, 노화, 당뇨, 쇼그렌증후군, 두경부 방사선 치료, 입으로 숨 쉬는 습관 등이 있습니다. 관리는 물을 자주 조금씩 마시기, 무설탕 껌이나 신맛 사탕으로 침샘 자극하기, 인공타액·보습 가글 사용, 카페인·술·흡연 줄이기가 기본이며, 원인 약물이 있다면 주치의와 조정을 상의할 수 있습니다. 구강건조증이 있다면 충치 위험이 높은 상태이므로 정기검진과 불소도포를 더 자주 받는 것이 좋습니다.' },
  { term: '입냄새(구취)', reading: 'Halitosis', category: '증상·질환', def: '입안 세균이 단백질을 분해하며 만드는 휘발성 황화합물이 주원인인 냄새 증상입니다. 구취의 원인은 80~90%가 입안에 있으며, 위장 문제는 생각보다 드뭅니다. 입안 원인 중에서도 혀 뒤쪽에 낀 백태, 치주염으로 생긴 깊은 잇몸 주머니 속 세균, 치아 사이에 남은 음식물 찌꺼기, 오래된 보철물 틈이 대표적입니다. 아침에 냄새가 심한 것은 수면 중 침 분비가 줄어 세균이 증식하기 때문인 자연스러운 현상입니다. 해결의 시작은 원인 제거입니다. 혀클리너로 혀 뒤쪽까지 닦고, 치실·치간칫솔로 치아 사이를 청소하고, 스케일링으로 치석을 제거하면 대부분 크게 개선됩니다. 치주염이 있다면 잇몸 치료가 근본 해결책입니다. 가글은 일시적 마스킹일 뿐이며 알코올 함유 가글은 입을 말려 오히려 역효과일 수 있습니다. 입이 마르지 않게 물을 자주 마시는 것도 중요합니다. 관리 후에도 지속되는 구취는 편도결석, 축농증, 역류성 식도염 등 다른 원인 감별이 필요합니다.', related: 'gum' },
  { term: '치경부 마모증', reading: 'Cervical Abrasion', category: '증상·질환', def: '치아와 잇몸이 만나는 목 부분이 V자 모양으로 패이는 질환입니다. 치아의 목 부분은 법랑질이 가장 얇은 취약 지대인데, 좌우로 세게 문지르는 잘못된 칫솔질, 뻣뻣한 칫솔모, 연마제가 강한 치약이 오랜 세월 반복되면 이 부위가 깎여 나갑니다. 이갈이나 이 악물기로 치아가 휘는 힘을 받을 때 목 부분 법랑질이 미세하게 떨어져 나가는 것(어브프랙션)도 원인으로 지목됩니다. 패인 부위로 상아질이 노출되면 찬물과 칫솔질에 시린 지각과민이 나타나고, 홈에 세균이 쌓여 충치가 생기기 쉬우며, 깊어지면 신경까지 위협해 신경치료가 필요해질 수 있습니다. 치료는 패인 깊이에 따라 다릅니다. 얕으면 시린이 치약과 지각과민 처치로 지켜보고, 뚜렷하게 패였으면 레진으로 메워 진행을 차단합니다. 무엇보다 원인 교정이 중요해, 부드러운 칫솔모로 위아래로 회전하듯 닦는 방법을 익히고 이갈이가 있다면 나이트가드를 병행해야 재발을 막을 수 있습니다.', related: 'cavity' },
  { term: '교합', reading: 'Occlusion', category: '구조·해부', def: '위턱과 아래턱의 치아가 서로 맞물리는 관계를 말합니다. 좋은 교합이란 여러 치아가 힘을 고르게 나누어 받으며 턱관절과 근육이 편안한 상태로 맞물리는 것을 의미합니다. 교합이 중요한 이유는 씹는 힘의 크기 때문입니다. 어금니에는 수십 kg의 힘이 가해지는데, 특정 치아만 먼저 세게 닿으면 그 치아에 힘이 집중되어 균열, 흔들림, 시림, 보철물 파손의 원인이 되고, 턱관절과 저작 근육에도 부담이 누적됩니다. 크라운이나 임플란트를 하고 나서 높이가 미세하게 맞지 않으면 불편감이 생기는 것도 교합의 민감함 때문으로, 사람은 머리카락 두께 수준의 높이 차이도 감지합니다. 그래서 모든 보철 치료의 마지막 단계는 교합지를 물려 닿는 지점을 확인하고 정밀하게 조정하는 과정입니다. 치아가 빠진 자리를 방치하면 주변 치아가 쓰러지고 맞은편 치아가 내려와 교합 전체가 무너질 수 있으므로, 상실 치아의 빠른 수복이 교합 보전의 기본입니다.', related: 'prosthetics' },
  { term: '유치와 영구치', reading: 'Primary / Permanent Teeth', category: '구조·해부', def: '유치(젖니)는 생후 6개월경부터 나기 시작해 총 20개가 자리 잡고, 만 6세 무렵부터 하나씩 빠지며 영구치 28개(사랑니 포함 시 32개)로 교체됩니다. 어차피 빠질 치아라고 유치 충치를 방치하는 것은 큰 오해입니다. 유치는 음식을 씹고 발음을 만들 뿐 아니라, 아래에서 자라는 영구치가 나올 자리를 지키는 공간 유지 장치입니다. 유치가 충치로 일찍 빠지면 옆 치아들이 그 공간으로 쓰러져 영구치가 나올 자리가 좁아지고 덧니와 부정교합의 원인이 됩니다. 유치 뿌리 끝 염증이 바로 아래 영구치 싹에 영향을 줄 수도 있습니다. 유치는 법랑질이 얇아 충치 진행이 어른보다 훨씬 빠르므로 정기검진이 더욱 중요합니다. 만 6세경 유치 어금니 뒤에서 나는 첫 영구치(6세 구치)는 유치로 오해받아 관리가 소홀해지기 쉬운데, 평생 써야 할 치아이므로 나오자마자 홈메우기(실런트)와 불소도포로 보호해 주는 것이 좋습니다.' },
  { term: '침(타액)', reading: 'Saliva', category: '구조·해부', def: '침샘에서 하루 1~1.5리터가량 분비되어 입안을 지키는 천연 보호액입니다. 침의 역할은 생각보다 훨씬 다양합니다. 첫째, 음식 찌꺼기와 세균을 씻어내는 자정 작용을 합니다. 둘째, 세균이 만든 산을 중화해 치아가 녹는 것을 막고, 침 속 칼슘과 인산이 초기 충치 부위의 미네랄을 다시 채워 넣는 재광화를 일으킵니다. 셋째, 항균 성분으로 세균 증식을 억제하고, 점막을 촉촉하게 보호하며, 소화 효소로 소화의 첫 단계를 담당합니다. 식사 후 입안이 산성으로 기울었다가 회복되는 것도 침의 완충 능력 덕분입니다. 그래서 침이 마르면 충치·잇몸병·구취·구내염이 한꺼번에 늘어납니다. 자기 전 양치가 특히 중요한 이유도 수면 중에는 침 분비가 크게 줄어 세균이 증식하기 가장 좋은 환경이 되기 때문입니다. 물을 자주 마시고, 꼭꼭 씹어 먹고, 무설탕 껌으로 침샘을 자극하는 습관은 비용이 들지 않는 훌륭한 충치 예방법입니다.' },
  { term: '플라크(치태)', reading: 'Dental Plaque', category: '예방·관리', def: '치아 표면에 형성되는 끈끈한 세균 덩어리 막입니다. 양치 후 몇 시간만 지나도 다시 만들어지기 시작하며, 혀로 치아를 쓸었을 때 매끈하지 않고 텁텁하게 느껴진다면 플라크가 쌓인 상태입니다. 플라크 1mg 속에는 수억 마리의 세균이 살고 있으며, 이 세균들이 당분을 먹고 산을 만들어 충치를 일으키고, 독소를 내뿜어 잇몸 염증(치은염·치주염)을 일으킵니다. 즉 충치와 잇몸병이라는 치과 2대 질환의 공통 원인이 바로 플라크입니다. 다행히 플라크는 아직 부드러운 상태라 칫솔과 치실만으로 충분히 제거할 수 있습니다. 문제는 제거되지 않고 남은 플라크로, 침 속 미네랄과 결합해 딱딱한 치석으로 굳으면 더 이상 칫솔로 제거할 수 없고 스케일링이 필요해집니다. 특히 잇몸 경계와 치아 사이가 플라크가 잘 남는 사각지대이므로, 이 부위를 의식하며 하루 2회 이상 꼼꼼히 닦고 치실을 병행하는 것이 모든 치과 질환 예방의 출발점입니다.', related: 'gum' },
  { term: '치석', reading: 'Calculus / Tartar', category: '예방·관리', def: '제거되지 않은 플라크가 침 속 칼슘·인 성분과 결합해 돌처럼 딱딱하게 굳은 것입니다. 플라크는 칫솔로 닦이지만 치석은 한번 굳으면 아무리 열심히 양치해도 제거되지 않으며, 오직 치과의 전문 기구(스케일링)로만 제거할 수 있습니다. 치석이 문제인 이유는 표면이 거칠어 그 위에 새로운 플라크가 훨씬 잘 달라붙는 세균의 아파트 역할을 하기 때문입니다. 치석 속과 주변의 세균이 잇몸에 지속적으로 염증을 일으켜 치은염과 치주염의 직접적 원인이 되고, 입냄새의 주요 원인이기도 합니다. 침샘 출구와 가까운 아래 앞니 안쪽과 위 어금니 바깥쪽에 특히 잘 생깁니다. 눈에 보이는 잇몸 위 치석보다 잇몸 속에 숨어 검붉게 굳은 치은연하 치석이 더 해로운데, 보이지 않는 곳에서 뼈를 녹이는 치주염을 조용히 진행시키기 때문입니다. 치석은 생기기 전에 플라크 단계에서 닦아내는 것이 최선이며, 이미 생긴 치석은 연 1~2회 스케일링으로 정기적으로 제거하는 것이 잇몸을 지키는 기본입니다.', related: 'gum' },
  { term: '홈메우기(실런트)', reading: 'Sealant', category: '예방·관리', def: '어금니 씹는 면의 깊고 좁은 홈을 치과용 재료로 미리 메워 충치를 예방하는 처치입니다. 어금니 씹는 면의 홈은 칫솔모 굵기보다 좁고 깊어 아무리 잘 닦아도 바닥까지 닿지 않으며, 실제로 어린이 충치의 대부분이 이 홈에서 시작됩니다. 실런트는 이 홈을 흐름성 좋은 재료로 채워 세균과 음식물이 낄 공간 자체를 없애는 원리로, 치아를 전혀 갈아내지 않고 마취도 필요 없는 통증 없는 예방 처치입니다. 시술은 치아 세척 후 재료를 홈에 흘려 넣고 빛으로 굳히면 끝나며 치아당 몇 분이면 충분합니다. 가장 효과적인 시기는 영구치 어금니가 나오는 만 6세와 12세 전후로, 치아가 나온 직후 충치가 생기기 전에 해주는 것이 이상적입니다. 만 18세 이하는 건강보험이 적용되어 부담도 적습니다. 다만 실런트는 씹는 면만 보호하므로 치아 사이 충치는 막지 못하며, 사용 중 일부가 떨어질 수 있어 정기검진 때 상태를 확인하고 필요하면 보충하는 관리가 함께 이뤄져야 합니다.', related: 'cavity' },
  { term: '올바른 칫솔질', reading: 'Tooth Brushing', category: '예방·관리', def: '칫솔질의 핵심은 세게 오래 닦는 것이 아니라 정확한 위치를 올바른 방향으로 닦는 것입니다. 충치와 잇몸병을 일으키는 플라크는 주로 치아와 잇몸의 경계, 치아 사이에 쌓이는데, 많은 분들이 치아 가운데의 넓은 면만 좌우로 문지르는 방식으로 닦습니다. 이 방식은 정작 경계부 플라크는 남기면서 치아 목 부분만 패이게 만듭니다(치경부 마모증). 권장 방법은 칫솔모를 치아와 잇몸 경계에 45도로 대고 잇몸에서 치아 방향으로 쓸어내리듯 회전시키는 회전법입니다. 한 부위에 10회가량, 안쪽 면과 씹는 면까지 순서를 정해 빠뜨리지 않고 닦으면 3분 정도 걸립니다. 칫솔은 부드러운 모를 선택하고 모가 벌어지면(약 2~3개월) 교체하며, 하루 2회 이상 특히 자기 전 칫솔질이 가장 중요합니다. 칫솔이 닿지 않는 치아 사이는 치실·치간칫솔이 담당하므로 반드시 병행해야 하며, 혀까지 닦으면 구취 예방에도 효과적입니다.', related: 'gum' },
  { term: '어금니와 앞니', reading: 'Molar / Incisor', category: '구조·해부', def: '치아는 위치에 따라 역할이 뚜렷하게 나뉩니다. 앞니(절치)는 음식을 자르고 발음과 심미를 담당하며, 송곳니(견치)는 음식을 찢고 턱이 옆으로 움직일 때 다른 치아를 보호하는 안내자 역할을 합니다. 그 뒤의 작은어금니와 큰어금니는 음식을 잘게 부수고 가는 분쇄기로, 씹는 힘의 대부분을 감당합니다. 이 역할 분담은 치료 계획에도 그대로 반영됩니다. 큰 힘을 받는 어금니 보철은 심미보다 강도가 우선되어 지르코니아 같은 튼튼한 재료를 선택하고, 앞니는 빛 투과성까지 재현하는 심미 재료가 우선됩니다. 특히 송곳니는 뿌리가 가장 길고 튼튼해 부분틀니의 지지대나 교합의 기준으로서 보존 가치가 매우 높은 치아입니다. 어금니 하나를 잃으면 나머지 치아들이 익숙하지 않은 분쇄 부담을 떠안아 연쇄적으로 무리가 가므로, 잘 안 보이는 치아라고 방치하지 말고 빠르게 수복하는 것이 다른 치아를 지키는 길입니다.' },
  { term: '치주인대', reading: 'Periodontal Ligament', category: '구조·해부', def: '치아 뿌리와 치조골 사이를 연결하는 얇은 섬유 조직층으로, 치아는 뼈에 직접 붙어 있는 것이 아니라 이 인대에 의해 그물침대처럼 매달려 있습니다. 치주인대는 세 가지 중요한 일을 합니다. 첫째, 씹을 때의 충격을 흡수하는 쿠션 역할로, 수십 kg의 저작력이 뼈에 그대로 전달되지 않게 완충합니다. 둘째, 정밀한 압력 센서 역할로, 머리카락 한 올을 물어도 알아챌 만큼 예민해 씹는 힘을 조절하게 하고 문제가 생기면 통증으로 경고합니다. 셋째, 혈관과 세포가 풍부해 뼈와 잇몸의 재생을 돕습니다. 치주염이 무서운 이유는 바로 이 인대와 주변 뼈를 파괴해 치아가 흔들리게 만들기 때문입니다. 임플란트에는 치주인대가 없어 씹는 감각이 자연치와 다르고 염증 경고 기능도 없으므로, 인대가 살아 있는 자연치를 최대한 보존하는 것이 치과 치료의 대원칙이 됩니다. 교정 치료에서 치아가 이동할 수 있는 것도 치주인대의 리모델링 능력 덕분입니다.', related: 'gum' },
  { term: '상악동', reading: 'Maxillary Sinus', category: '구조·해부', def: '위턱뼈 속, 코 양옆에 자리한 공기 주머니로 부비동(축농증이 생기는 그 공간) 중 가장 큽니다. 치과에서 상악동이 중요한 이유는 위턱 어금니 뿌리와 매우 가깝기 때문입니다. 어금니 뿌리 끝과 상악동 바닥 사이의 뼈가 종잇장처럼 얇거나 뿌리가 상악동 안으로 살짝 들어가 있는 경우도 흔합니다. 그래서 위 어금니를 뽑고 오랜 시간이 지나면 잇몸뼈가 흡수되는 동시에 상악동이 아래로 확장되어, 임플란트를 심을 뼈 높이가 몇 mm밖에 남지 않게 됩니다. 이때 필요한 것이 상악동 바닥의 막을 들어 올리고 뼈이식재를 채우는 상악동거상술입니다. 또 위 어금니의 뿌리 끝 염증이 상악동으로 번져 치성 축농증을 일으키기도 하는데, 코 치료로 낫지 않는 축농증의 원인이 치아인 경우가 있어 감별이 필요합니다. 이런 해부학적 관계 때문에 위턱 어금니의 임플란트와 발치는 CT로 상악동 상태를 정확히 확인한 뒤 계획하는 것이 안전의 기본입니다.', related: 'implant' },
  { term: '뼈이식재', reading: 'Bone Graft Material', category: '재료·장비', def: '부족한 잇몸뼈를 재건할 때 사용하는 재료로, 새 뼈가 자라 들어올 뼈대(스캐폴드) 역할을 합니다. 출처에 따라 자가골(본인 뼈), 동종골(기증된 사람 뼈), 이종골(주로 소뼈 유래), 합성골 네 가지로 나뉩니다. 자가골은 본인 조직이라 뼈 형성 능력이 가장 우수하지만 채취 부위가 추가로 필요하고 양이 제한적입니다. 이종골은 뼈의 미세 구조가 사람 뼈와 유사하고 천천히 흡수되어 부피 유지가 좋아 임플란트 뼈이식에서 가장 널리 쓰이며, 동종골과 합성골도 각각의 장점에 따라 활용됩니다. 실제 임상에서는 두 종류 이상을 혼합해 각 재료의 장점을 조합하는 경우가 많고, 이식재가 안정적으로 자리 잡도록 차폐막으로 덮어 잇몸 세포의 침입을 막기도 합니다. 모든 이식재는 엄격한 처리·멸균 공정을 거쳐 안전성이 관리됩니다. 이식된 재료는 수개월에 걸쳐 본인의 새 뼈로 서서히 대체되며, 이 치유 기간을 충분히 기다리는 것이 임플란트 성공의 조건이 됩니다.', related: 'implant' },
  { term: '어버트먼트', reading: 'Abutment', category: '재료·장비', def: '임플란트에서 뼈에 심긴 인공 뿌리(픽스처)와 겉으로 보이는 인공 치아(크라운)를 연결하는 중간 기둥 부품입니다. 임플란트는 픽스처-어버트먼트-크라운의 3층 구조로 이뤄지는데, 어버트먼트는 그중 힘을 전달하고 크라운의 방향과 높이를 결정하는 허리 역할을 합니다. 규격화된 기성 어버트먼트와, 환자의 잇몸 형태·치아 각도에 맞게 개별 제작하는 맞춤(커스텀) 어버트먼트가 있으며, 맞춤형은 잇몸 라인에 자연스럽게 맞아 음식물 끼임이 적고 심미성과 청소 용이성이 우수해 활용이 늘고 있습니다. 재질은 강도가 우수한 티타늄이 기본이고, 앞니처럼 잇몸 위로 금속색이 비칠 수 있는 부위에는 지르코니아 어버트먼트를 쓰기도 합니다. 사용 중 어버트먼트를 고정하는 나사가 미세하게 풀리면 크라운이 흔들리거나 음식물이 끼기 시작하는데, 이는 재조임으로 간단히 해결되지만 방치하면 나사 파절로 이어질 수 있으므로 정기검진에서 점검받는 것이 중요합니다.', related: 'implant' },
  { term: '레이저 치료', reading: 'Dental Laser', category: '재료·장비', def: '빛 에너지를 이용해 잇몸 등 연조직을 절개·소독하거나 치료 부위를 활성화하는 장비입니다. 치과용 레이저의 장점은 절개와 동시에 지혈이 이뤄져 출혈이 적고, 시술 부위가 살균되어 감염 위험이 낮으며, 통증과 부기가 적어 회복이 빠르다는 점입니다. 메스 대신 레이저로 잇몸을 다듬는 잇몸성형, 잇몸 착색(멜라닌 색소) 제거, 구내염 통증 완화 처치, 임플란트 주위염 부위의 소독, 신경치료 시 근관 내 살균 보조 등 활용 범위가 넓습니다. 물방울과 레이저를 함께 쏘는 수증기 폭발 방식의 경조직 레이저는 치아 삭제에도 일부 활용되어, 기계 소리와 진동에 공포가 큰 환자에게 대안이 되기도 합니다. 다만 레이저가 모든 치료에서 기존 방식보다 우월한 것은 아니며, 치료 목적에 따라 전통적 방식과 레이저의 장점을 조합하는 것이 합리적입니다. 시술 부담을 줄이는 보조 도구로서 특히 잇몸 시술과 소독 영역에서 가치가 큰 장비입니다.', related: 'gum' },
  { term: '루페(확대경)', reading: 'Loupe', category: '재료·장비', def: '치과의사가 안경처럼 착용하는 확대 장비로, 치료 부위를 수 배 확대해 보면서 진료하게 해줍니다. 치아 하나의 폭은 1cm 남짓이고 그 안에서 다뤄야 할 충치 경계, 균열선, 보철물 경계선은 훨씬 미세합니다. 맨눈으로는 한계가 있는 이 세계를 확대 시야로 보면 치료의 정밀도가 달라집니다. 충치를 제거할 때 건강한 치질은 최대한 남기고 감염 부위만 정확히 걷어낼 수 있고, 크라운의 경계를 매끈하게 다듬어 세균이 침투할 틈을 줄일 수 있으며, 미세한 균열이나 초기 충치를 조기에 발견할 확률도 높아집니다. 확대율이 더 높은 미세현미경이 신경치료 같은 초정밀 영역을 담당한다면, 루페는 일상 진료 전반의 기본 정밀도를 끌어올리는 장비라 할 수 있습니다. 조명이 부착된 루페는 입안 깊숙한 곳까지 그림자 없이 밝혀줍니다. 장비 자체가 치료 결과를 보장하는 것은 아니지만, 확대 시야에서의 진료가 정밀함의 기본 조건이 되는 것은 분명합니다.' },
  { term: '치과공포증', reading: 'Dental Phobia', category: '증상·질환', def: '치과 진료에 대한 두려움이 지나쳐 치료를 미루거나 회피하게 되는 상태입니다. 단순한 긴장을 넘어 예약 전날부터 잠을 설치고, 기계 소리만 들어도 심장이 뛰고, 결국 몇 년씩 치과를 피하는 분들이 적지 않습니다. 문제는 회피의 대가입니다. 초기에 간단히 끝났을 치료가 방치되어 신경치료, 발치, 임플란트로 커지고, 치료 규모가 커질수록 공포도 더 커지는 악순환에 빠집니다. 과거의 아픈 치료 경험이 원인인 경우가 가장 많습니다. 다행히 요즘 치과에는 공포를 줄이는 장치가 많습니다. 표면마취와 무통마취기로 주사 통증을 최소화하고, 치료 전 과정을 미리 설명해 예측 가능성을 높이며, 힘들면 손을 들어 언제든 멈출 수 있다는 약속만으로도 불안이 크게 줄어듭니다. 공포가 심한 경우 의식하진정(수면치료) 하에 편안하게 치료받는 방법도 있습니다. 두려움을 숨기지 말고 첫 상담에서 솔직하게 이야기하는 것이 편안한 치료의 출발점입니다.' },
  { term: '수면치료(의식하진정)', reading: 'Sedation', category: '치료·시술', def: '진정 약물을 사용해 얕은 수면과 비슷한 편안한 상태에서 치료받는 방법입니다. 정확한 명칭은 의식하진정법으로, 전신마취처럼 의식을 완전히 잃는 것이 아니라 의식과 호흡은 유지된 채 불안과 긴장이 크게 줄어든 상태가 됩니다. 치료 중 지시에 반응할 수 있지만 시간이 어떻게 갔는지 모를 만큼 편안하고, 치료 과정이 거의 기억나지 않는 경우가 많습니다. 치과공포증이 심한 분, 구역 반사가 심해 기구만 들어가도 헛구역질이 나는 분, 임플란트 수술이나 사랑니 발치처럼 긴 치료를 한 번에 받아야 하는 분에게 특히 유용합니다. 시행 전 건강 상태와 복용 약물을 확인하는 사전 평가가 필수이며, 치료 중에는 산소포화도·혈압 등 생체 신호를 지속 모니터링해 안전을 관리합니다. 치료 후에는 약 기운이 남아 있으므로 당일 운전은 금물이고 보호자 동반 귀가를 권합니다. 공포 때문에 치료를 미뤄온 분들이 밀린 치료를 해결하는 현실적인 돌파구가 됩니다.' },
  { term: '금니(골드크라운)', reading: 'Gold Crown', category: '재료·장비', def: '금 합금으로 만든 크라운으로, 오랜 세월 어금니 보철의 표준이었던 재료입니다. 금니의 강점은 재료의 성질에 있습니다. 자연치와 단단함이 비슷해 맞물리는 치아를 마모시키지 않고, 깨지지 않으며, 얇게 만들어도 강도가 유지되어 치아를 상대적으로 적게 갈아낼 수 있습니다. 늘어나는 성질(연성) 덕분에 치아와의 경계가 정밀하게 적합되어 이차 충치 위험이 낮고, 부식되지 않아 수십 년 사용 사례도 드물지 않습니다. 단점은 명확합니다. 금색이 그대로 드러나 심미성이 떨어지고, 금 시세에 따라 비용이 높습니다. 최근에는 강도와 심미성을 겸비한 지르코니아가 발전하면서 선택 비중이 크게 이동했지만, 이갈이가 심해 세라믹 파절이 걱정되는 경우나 씹는 면 마모 조화가 중요한 경우에는 여전히 금니가 훌륭한 선택지입니다. 눈에 잘 띄지 않는 최후방 어금니라면 심미보다 기능적 수명을 우선해 금니를 고려할 가치가 충분합니다.', related: 'prosthetics' },
  { term: '임시치아', reading: 'Temporary Crown', category: '치료·시술', def: '크라운·라미네이트·임플란트 보철이 완성되기 전까지 치아를 보호하고 기능을 유지하기 위해 임시로 장착하는 치아입니다. 단순히 빈자리를 가리는 용도가 아니라 여러 중요한 역할을 합니다. 갈아낸 치아의 시린 증상을 막아주고, 치아가 움직이지 않게 자리를 지켜 최종 보철물이 정확히 들어맞게 하며, 잇몸 형태를 유지하고, 발음과 심미를 임시로 회복해 일상생활을 가능하게 합니다. 앞니 심미 치료에서는 임시치아 단계에서 모양과 길이를 미리 시험해 보고 환자 의견을 반영해 최종 보철물 디자인을 다듬는 시뮬레이션 역할도 합니다. 다만 임시치아는 임시 접착제로 붙어 있고 강도도 약하므로 주의가 필요합니다. 끈적한 음식(캐러멜, 엿, 껌)은 임시치아를 빼낼 수 있고, 딱딱한 음식은 깨뜨릴 수 있으므로 반대쪽으로 씹는 것이 안전합니다. 빠지거나 깨졌다면 방치하지 말고 바로 치과에 연락해야 치아 이동과 시림을 막을 수 있습니다.', related: 'prosthetics' },
  { term: '치아 파절(깨진 치아)', reading: 'Tooth Fracture', category: '증상·질환', def: '외상이나 씹는 힘에 의해 치아가 깨지거나 부러진 상태입니다. 넘어짐·부딪힘 같은 사고뿐 아니라 딱딱한 음식, 이갈이, 큰 충전물로 약해진 치아에서도 발생합니다. 치료는 깨진 깊이가 결정합니다. 법랑질만 살짝 깨졌다면 레진으로 간단히 수복하고, 상아질까지 깨져 시리다면 레진이나 크라운으로 보호하며, 신경이 노출되면 신경치료 후 크라운이 필요합니다. 뿌리까지 세로로 쪼개진 경우에는 안타깝게도 발치가 불가피한 경우가 많습니다. 외상으로 치아가 통째로 빠졌다면(완전탈구) 시간과의 싸움입니다. 뿌리 표면을 만지거나 문지르지 말고 우유나 식염수에 담가 30분~1시간 안에 치과에 도착하면 다시 심어 살릴 가능성이 있습니다. 깨진 직후 증상이 없더라도 신경 손상이 뒤늦게 나타날 수 있어 몇 달 뒤 치아가 검게 변색되기도 하므로, 외상 후에는 증상이 없어도 검진과 추적 관찰을 받아두는 것이 안전합니다.', related: 'endo' },
  { term: '치아 변색', reading: 'Tooth Discoloration', category: '증상·질환', def: '치아 색이 노랗거나 어둡게 변하는 현상으로, 원인에 따라 외인성과 내인성으로 나뉩니다. 외인성 변색은 커피·차·와인·카레 같은 색소 음식과 흡연으로 치아 표면에 착색이 쌓이는 것으로, 스케일링과 전문가 치면 세마로 상당 부분 제거되고 미백 치료 반응도 좋습니다. 내인성 변색은 치아 내부의 문제입니다. 나이가 들며 법랑질이 얇아지고 속의 노란 상아질이 두꺼워져 자연스럽게 어두워지는 노화성 변색, 외상이나 신경 괴사로 치아 하나만 회색·검은색으로 변하는 실활치 변색, 어릴 때 복용한 테트라사이클린 계열 항생제로 인한 띠 모양 변색 등이 대표적입니다. 치료는 원인 진단에서 출발합니다. 전반적 변색은 치아미백으로, 신경이 죽은 치아는 그 치아 내부에 미백제를 넣는 실활치 미백으로, 미백으로 한계가 있는 심한 변색은 라미네이트나 크라운으로 색 자체를 새로 만드는 방법을 씁니다. 갑자기 치아 하나가 어두워졌다면 신경 상태 검사가 우선입니다.', related: 'aesthetic' },
  { term: '벌어진 앞니(정중이개)', reading: 'Diastema', category: '증상·질환', def: '앞니 사이가 벌어져 틈이 있는 상태로, 특히 위 앞니 가운데가 벌어진 것을 정중이개라고 합니다. 원인은 다양합니다. 윗입술 안쪽 인대(순소대)가 치아 사이까지 깊게 내려와 붙은 경우, 치아 크기가 턱에 비해 작은 경우, 혀로 앞니를 미는 습관, 치주염으로 치아가 이동한 경우 등이 있습니다. 특히 성인이 되어 없던 틈이 새로 생기거나 점점 벌어진다면 치주염으로 뼈 지지가 약해진 신호일 수 있어 잇몸 검사가 우선입니다. 치료는 틈의 크기와 원인에 따라 선택합니다. 작은 틈은 치아를 거의 갈지 않고 레진을 붙여 하루에 개선할 수 있고, 여러 개의 틈이나 모양 개선까지 원하면 라미네이트가 완성도 높은 결과를 줍니다. 틈이 크거나 교합 문제가 동반되면 교정 치료로 치아 자체를 이동시키는 것이 근본적입니다. 순소대가 원인이면 재발 방지를 위해 간단한 소대 절제를 병행하기도 합니다. 원인 진단 없이 틈만 메우면 재발할 수 있어 정확한 검사가 중요합니다.', related: 'aesthetic' },
  { term: '검은 삼각형(치간 공극)', reading: 'Black Triangle', category: '증상·질환', def: '치아와 치아 사이, 잇몸 쪽에 검은 삼각형 모양의 빈 공간이 생기는 현상입니다. 원래 이 공간은 뾰족하게 솟은 잇몸(치간유두)이 채우고 있는데, 치주염으로 뼈가 내려앉거나, 잇몸 치료·교정 후 부어 있던 잇몸이 건강한 위치로 자리 잡으면서 유두가 낮아지면 삼각형 틈이 드러납니다. 나이가 들며 잇몸이 자연 퇴축해도 생길 수 있습니다. 심미적으로 거슬릴 뿐 아니라 음식물이 잘 끼고 발음 시 침이 튀는 불편도 있습니다. 안타깝게도 한번 낮아진 치간유두를 원래대로 재생시키는 것은 매우 어렵기 때문에, 치료는 공간을 채우는 방향으로 접근합니다. 치아 옆면에 레진을 자연스럽게 붙여 틈을 좁히거나, 라미네이트·크라운 형태를 조정해 공간을 가리는 방법이 대표적입니다. 교정으로 치아 위치를 조정해 개선하기도 합니다. 무엇보다 원인인 치주염이 진행 중이라면 잇몸 치료가 먼저이며, 예방 차원에서는 잇몸이 내려앉기 전에 치주 건강을 지키는 것이 최선입니다.', related: 'gum' },
  { term: '잇몸 퇴축', reading: 'Gum Recession', category: '증상·질환', def: '잇몸이 내려앉아 치아 뿌리가 드러나는 현상입니다. 치아가 길어 보이고, 드러난 뿌리 부위가 찬 것에 시리고, 뿌리는 법랑질이 없어 충치에도 취약해집니다. 심미적으로도 나이 들어 보이는 인상을 줍니다. 원인은 복합적입니다. 치주염으로 뼈가 녹으면서 잇몸이 함께 내려가는 경우가 가장 흔하고, 옆으로 세게 문지르는 잘못된 칫솔질, 타고나길 얇은 잇몸, 이갈이로 인한 과도한 힘, 치아가 치열 밖으로 돌출된 위치 등이 작용합니다. 한번 내려간 잇몸은 저절로 다시 올라오지 않습니다. 치료의 첫걸음은 진행을 멈추는 것으로, 치주염이 있다면 잇몸 치료를, 칫솔질 습관이 원인이면 부드러운 칫솔과 회전법으로 교정합니다. 노출된 뿌리의 시림은 지각과민 처치나 레진으로 관리하고, 퇴축이 심하거나 심미가 중요한 부위는 입천장 등에서 잇몸 조직을 옮겨 덮는 잇몸이식술로 회복을 시도할 수 있습니다. 시리다고 더 세게 닦는 것은 악화를 부르는 흔한 실수입니다.', related: 'gum' },
  { term: '돌출입과 부정교합', reading: 'Malocclusion', category: '증상·질환', def: '치아의 배열이나 위아래 턱의 맞물림이 어긋난 상태를 부정교합이라 합니다. 삐뚤빼뚤한 치열(총생), 벌어진 치아, 위 앞니가 많이 튀어나온 돌출, 아래턱이 나온 주걱턱(3급), 위아래 앞니가 닿지 않는 개방교합 등 형태가 다양합니다. 부정교합은 외모 문제로만 생각하기 쉽지만 기능적 영향이 큽니다. 겹친 치아는 칫솔이 닿지 않아 충치와 잇몸병이 잘 생기고, 특정 치아에 힘이 집중되어 마모와 파절 위험이 높아지며, 발음과 씹는 효율에도 영향을 줍니다. 치료는 교정이 기본이며, 성장기에는 턱 성장을 유도하는 치료가 가능해 시기를 놓치지 않는 것이 중요합니다. 성인 교정도 나이 제한은 없으나 잇몸 건강이 전제 조건입니다. 골격 차이가 큰 경우 수술과 교정을 병행하기도 합니다. 교정 여부와 별개로, 부정교합이 있는 분은 충치·잇몸병 위험이 구조적으로 높으므로 치실 사용과 정기검진을 더 철저히 하는 것이 좋습니다.' },
  { term: '스플린트(교합안정장치)', reading: 'Occlusal Splint', category: '치료·시술', def: '턱관절 장애와 이갈이 치료에 사용하는 투명한 마우스피스 형태의 장치로, 주로 수면 중 착용합니다. 위 치아 또는 아래 치아 전체를 덮는 단단한 재질의 맞춤 장치이며, 물리는 면이 정밀하게 조정되어 있어 단순 보호용 나이트가드보다 치료적 성격이 강합니다. 작동 원리는 세 가지입니다. 첫째, 턱관절이 편안한 위치에서 물리도록 유도해 관절 속 디스크와 조직의 부담을 줄입니다. 둘째, 특정 치아에 집중되던 힘을 장치 전체로 분산시킵니다. 셋째, 무는 순간 치아 접촉 감각이 달라져 이 악무는 근육의 활성 자체가 줄어드는 효과가 있습니다. 착용 초기에는 이물감과 침 고임이 있지만 대부분 1~2주 내 적응하며, 착용 기간 중에는 정기적으로 내원해 물리는 면을 재조정해야 치료 효과가 유지됩니다. 임의로 장치를 갈아 끼우거나 기성품으로 대체하면 교합이 틀어질 수 있어 주의가 필요합니다. 턱관절 보존 치료의 중심 도구로, 행동요법·물리치료와 병행할 때 효과가 좋습니다.', related: 'tmj' },
  { term: '치아 크기 비율과 스마일 라인', reading: 'Smile Design', category: '치료·시술', def: '아름다운 미소를 결정하는 요소를 분석해 치료 계획에 반영하는 심미 치료의 설계 개념입니다. 매력적인 미소에는 공통된 규칙이 있습니다. 위 앞니의 폭과 길이 비율(약 75~80%), 가운데 앞니에서 옆 치아로 갈수록 일정한 비율로 작아 보이는 조화, 웃을 때 위 앞니 끝을 잇는 선이 아랫입술 곡선과 나란한 스마일 라인, 잇몸 노출량(2~3mm 이내), 얼굴 중심선과 치아 중심선의 일치 등입니다. 스마일 디자인은 이런 요소를 사진·영상·디지털 스캔으로 분석하고, 컴퓨터 시뮬레이션이나 목업(치아에 직접 입혀보는 시안)으로 결과를 미리 보여준 뒤 치료를 진행하는 방식입니다. 라미네이트 몇 개를 붙이는 단순 시술이 아니라, 잇몸 라인 조정·미백·보철을 조합해 얼굴 전체와 조화로운 미소를 설계하는 것이 핵심입니다. 환자가 원하는 이미지(자연스러움, 화사함 등)를 시안 단계에서 충분히 소통할수록 만족도가 높아집니다.', related: 'aesthetic' },
  { term: '치과 건강보험 적용', reading: 'Dental Insurance Coverage', category: '예방·관리', def: '치과 진료 중 건강보험이 적용되는 항목을 알아두면 부담을 크게 줄일 수 있습니다. 대표적인 보험 적용 항목은 진찰·엑스레이, 연 1회 스케일링(만 19세 이상), 충치의 아말감·글래스아이오노머 충전, 신경치료, 발치, 잇몸 치료(치근활택술·치주수술 포함), 만 12세 이하 영구치 레진 충전과 만 18세 이하 홈메우기입니다. 어르신을 위한 항목도 있습니다. 만 65세 이상은 임플란트 2개(본인부담 30%)와 틀니(7년 주기, 본인부담 30%)가 보험 적용됩니다. 반면 심미 목적의 라미네이트·미백·교정(일부 선천성 제외), 금니·지르코니아 크라운, 일반 성인의 레진 충전 등은 비급여입니다. 같은 충치라도 재료 선택에 따라 보험 여부가 달라질 수 있으므로, 치료 전 상담에서 보험 적용 여부와 대안을 함께 확인하는 것이 좋습니다. 보험 항목은 제도 개편에 따라 달라질 수 있어 치료 시점 기준으로 안내받는 것이 정확합니다.' },
  { term: '임산부 치과 치료', reading: 'Dental Care in Pregnancy', category: '예방·관리', def: '임신 중에도 치과 치료는 가능하며, 오히려 필요한 치료를 미루는 것이 더 위험할 수 있습니다. 임신 중에는 호르몬 변화로 잇몸이 붓고 피가 잘 나는 임신성 치은염이 흔하고, 입덧으로 인한 위산과 잦은 간식으로 충치 위험도 높아집니다. 심한 치주염은 조산·저체중아와의 연관성이 보고되어 있어 잇몸 관리가 특히 중요합니다. 치료 시기는 임신 중기(14~28주)가 가장 안정적이며, 스케일링·충치 치료·응급 신경치료 모두 이 시기에 안전하게 받을 수 있습니다. 치과 국소마취제는 태아에 안전한 것으로 확인된 약제를 사용하고, 꼭 필요한 엑스레이는 납 방호복을 착용하면 태아 영향이 무시할 수준입니다. 다만 심미 치료나 임플란트 같은 선택적 치료는 출산 후로 미루는 것이 일반적입니다. 가장 좋은 것은 임신 준비 단계에서 미리 검진과 스케일링을 받아두는 것이며, 임신 사실은 반드시 치과에 알려 치료 계획에 반영하도록 해야 합니다.' },
  { term: '어린이 치과 검진', reading: 'Pediatric Dental Check-up', category: '예방·관리', def: '아이의 첫 치과 방문은 첫 유치가 난 후, 늦어도 돌 무렵을 권장합니다. 이르다고 느껴질 수 있지만 목적은 치료가 아니라 예방과 적응입니다. 충치 위험도 평가, 이유식·수유 습관 상담, 불소 사용법 안내를 받고, 아이가 치과라는 공간에 아프기 전에 익숙해지는 것이 핵심입니다. 아픈 경험으로 치과를 처음 만나면 공포가 각인되어 평생 치과 회피로 이어지기 쉽습니다. 이후에는 3~6개월 간격 정기검진으로 충치를 조기에 잡고, 만 6세 전후 첫 영구치 어금니가 나오면 홈메우기와 불소도포로 보호합니다. 유치 충치는 진행이 빠르고 영구치 배열에 영향을 주므로 빠질 치아라고 방치하면 안 됩니다. 교정 관점의 첫 평가는 만 7세 전후가 권장되는데, 이 시기에 턱 성장 문제나 공간 부족을 발견하면 성장을 이용한 조기 개입이 가능하기 때문입니다. 손가락 빨기·입호흡 같은 습관도 이때 함께 점검하면 좋습니다.' },
  { term: '스케일링 후 시림', reading: 'Post-scaling Sensitivity', category: '예방·관리', def: '스케일링 후 치아가 시리고 이 사이가 벌어진 것 같다고 느끼는 분들이 많은데, 대부분 치료의 부작용이 아니라 원래 상태가 드러난 것입니다. 두껍게 붙어 있던 치석은 그동안 치아 뿌리를 덮는 담요이자 치아 사이를 메우는 시멘트처럼 작용하고 있었습니다. 치석을 제거하면 그 아래 이미 노출되어 있던 뿌리 면이 공기와 찬물에 직접 닿게 되어 시림이 나타나고, 치석이 채우던 공간이 비면서 이 사이가 벌어진 듯 느껴집니다. 또 치석의 압박과 염증으로 부어 있던 잇몸이 건강하게 가라앉으면서 뿌리가 조금 더 드러나 보일 수 있습니다. 이런 시림은 대부분 1~2주, 길어도 한 달 내에 적응되며, 시린이 전용 치약이 회복을 돕습니다. 시리다고 스케일링을 피하면 치석이 계속 뼈를 녹여 결국 치아를 잃게 되므로 본말이 전도된 선택입니다. 오히려 정기적으로 스케일링을 받으면 치석이 얇을 때 제거되어 시림도 훨씬 덜합니다.', related: 'gum' },
  { term: '치과 응급상황 대처', reading: 'Dental Emergency', category: '예방·관리', def: '갑작스러운 치과 응급상황에서의 올바른 초기 대처는 치아의 운명을 바꿀 수 있습니다. 가장 시간이 급한 것은 치아가 통째로 빠진 경우(완전탈구)입니다. 치아 머리 부분만 잡고(뿌리는 만지지 않기), 흙이 묻었어도 문지르지 말고 우유·식염수에 담거나 입안 볼 쪽에 물고 30분~1시간 내 치과로 가면 재식립 성공 가능성이 있습니다. 물로 박박 씻거나 휴지에 싸서 말리면 뿌리 표면 세포가 죽어 살릴 수 없게 됩니다. 치아가 깨진 경우 조각을 찾아 물에 담아 가져가면 접착 복원이 가능할 수 있습니다. 밤에 극심한 치통이 올 때는 진통제(이부프로펜 등)를 복용하되, 아스피린을 잇몸에 직접 문지르는 민간요법은 화학 화상을 일으키므로 금물입니다. 얼굴이 붓고 열이 나는 경우는 감염이 퍼지는 신호로 응급실 방문이 필요할 수 있습니다. 발치 후 멈추지 않는 출혈은 깨끗한 거즈를 30분씩 단단히 물어 압박하는 것이 기본입니다.' },
  { term: '흡연과 구강 건강', reading: 'Smoking & Oral Health', category: '예방·관리', def: '흡연은 구강 건강에 가장 해로운 생활 습관입니다. 담배의 니코틴은 잇몸 혈관을 수축시켜 혈액 공급을 줄이는데, 이 때문에 흡연자는 치주염이 있어도 잇몸 출혈이 적어 병을 늦게 발견하고, 조직 회복력이 떨어져 치료 후에도 잘 낫지 않습니다. 흡연자의 치주염 위험은 비흡연자의 몇 배에 달하며 진행 속도도 빠릅니다. 임플란트에는 특히 치명적입니다. 흡연은 뼈와 임플란트의 결합을 방해해 실패율을 유의하게 높이고, 임플란트 주위염 위험도 커지므로 최소한 수술 전후 몇 주만이라도 금연이 강력히 권고됩니다. 발치 후 드라이소켓, 구강암과 전암 병소(백반증), 심한 착색과 구취, 미각 저하도 흡연과 직결됩니다. 전자담배도 니코틴의 혈관 수축 작용은 동일해 안전한 대안이 아닙니다. 금연은 시기와 무관하게 효과가 있어, 끊는 순간부터 잇몸 혈류가 회복되기 시작합니다. 당장 어렵다면 정기검진 간격을 좁혀 관리하는 것이 차선책입니다.', related: 'gum' },
  { term: '당뇨와 잇몸 건강', reading: 'Diabetes & Gum Disease', category: '예방·관리', def: '당뇨와 치주염은 서로를 악화시키는 양방향 관계로 잘 알려져 있습니다. 혈당이 높으면 침 속 당분이 늘어 세균이 번식하기 좋아지고, 면역 기능과 상처 회복력이 떨어져 잇몸 염증이 잘 생기고 잘 낫지 않습니다. 당뇨 환자의 치주염 위험은 비당뇨인의 2~3배로, 치주염은 당뇨의 6번째 합병증이라고도 불립니다. 반대 방향도 성립합니다. 치주염의 만성 염증 물질이 혈류를 타고 퍼지면 인슐린 저항성을 높여 혈당 조절을 방해하며, 실제로 치주 치료 후 당화혈색소가 개선된다는 연구들이 보고되어 있습니다. 즉 잇몸 치료가 혈당 관리의 일부인 셈입니다. 당뇨가 있다면 3~4개월 간격의 잇몸 정기 관리, 철저한 치실 사용, 구강건조 관리가 권장되며, 임플란트나 발치 같은 수술적 치료는 혈당이 안정적으로 조절되는 상태에서 진행하는 것이 안전합니다. 치과 방문 시 당뇨 여부와 최근 혈당 상태, 복용 약물을 꼭 알려주는 것이 좋습니다.', related: 'gum' },
  { term: '골다공증 약과 치과 치료', reading: 'Bisphosphonate & Dentistry', category: '예방·관리', def: '골다공증 치료제 중 비스포스포네이트 계열(포사맥스, 본비바 등)과 데노수맙 주사(프롤리아)를 복용·투여 중인 분은 발치나 임플란트 전에 반드시 치과에 알려야 합니다. 이 약들은 뼈를 파괴하는 세포의 작용을 억제해 골다공증에는 도움이 되지만, 턱뼈의 정상적인 재생·치유 능력도 함께 낮춥니다. 그 결과 발치처럼 뼈가 노출되는 치료 후 상처가 아물지 않고 턱뼈가 괴사하는 약물 관련 턱뼈괴사(MRONJ)가 드물게 발생할 수 있습니다. 위험도는 복용 기간(특히 4년 이상), 주사제 여부, 스테로이드 병용 등에 따라 달라지며, 발생 빈도 자체는 낮으므로 지나친 공포보다는 관리가 중요합니다. 원칙은 예방입니다. 약 시작 전에 필요한 발치와 치과 치료를 미리 끝내두는 것이 가장 좋고, 복용 중이라면 정기검진으로 발치가 필요한 상황 자체를 만들지 않는 것입니다. 수술이 불가피한 경우 처방 의사와 협의해 시기와 방법을 조율하며, 임의로 약을 중단해서는 안 됩니다.' },
  { term: '치과 정기검진 주기', reading: 'Recall Interval', category: '예방·관리', def: '정기검진은 6개월 간격이 표준처럼 알려져 있지만, 실제 적정 주기는 개인의 위험도에 따라 다릅니다. 충치가 잘 생기는 체질, 치주염 치료 병력, 임플란트·교정장치 사용, 당뇨, 흡연, 구강건조증, 이갈이가 있는 분은 3~4개월 간격의 짧은 주기가 권장됩니다. 특히 치주염 치료를 받은 분은 3개월 간격의 유지 관리가 재발 방지의 핵심이라는 근거가 확립되어 있습니다. 반대로 충치·잇몸병 병력이 거의 없고 관리가 잘되는 분은 1년 간격도 무리가 없습니다. 검진 주기를 지키는 것이 중요한 이유는 치과 질환의 속도에 있습니다. 충치가 법랑질을 지나 상아질에 들어서면 진행이 빨라지고, 치주염은 증상 없이 뼈를 녹입니다. 6개월~1년의 간격은 문제가 생겨도 간단한 치료 단계에서 잡아낼 수 있는 안전망인 셈입니다. 자신의 위험도를 치과와 상의해 맞춤 주기를 정하고, 스케일링(연 1회 보험 적용)과 묶어 습관화하면 평생 치과 비용을 가장 크게 아끼는 방법이 됩니다.', related: 'cavity' },
  { term: '드라이소켓', reading: 'Dry Socket', category: '증상·질환', def: '발치 후 상처를 보호하던 혈병(피딱지)이 떨어져 나가거나 제대로 형성되지 않아 뼈가 그대로 노출되는 상태입니다. 발치 자리는 혈병이 자연 밴드 역할을 하며 아물어 가는데, 이것이 소실되면 뼈와 신경이 공기·음식물에 직접 노출되어 발치 2~4일 후부터 극심한 통증이 시작됩니다. 진통제가 잘 듣지 않고 귀와 관자놀이까지 뻗치는 통증, 입냄새, 입안의 불쾌한 맛이 특징이며, 특히 아래턱 사랑니 발치 후에 흔합니다. 위험 요인은 흡연(빨아들이는 압력+니코틴의 혈류 방해), 빨대 사용, 침 뱉기, 과격한 가글, 피임약 복용 등입니다. 예방을 위해 발치 후 최소 3일간은 흡연과 빨대를 피하고, 첫날은 가글 대신 물을 머금었다 흘리는 정도로만 헹구는 것이 좋습니다. 드라이소켓이 생기면 치과에서 상처 세척 후 진정 드레싱을 넣어 통증을 조절하며, 며칠 간격의 드레싱 교체로 대부분 1~2주 내 회복됩니다. 참지 말고 바로 내원하는 것이 답입니다.', related: 'wisdom' },
  { term: '매복 사랑니', reading: 'Impacted Wisdom Tooth', category: '증상·질환', def: '잇몸이나 뼈 속에 완전히 또는 부분적으로 묻혀 정상적으로 나오지 못한 사랑니를 말합니다. 현대인의 턱은 사랑니가 자리 잡기에 좁아, 옆으로 눕거나(수평 매복) 비스듬히 기울어진 채 묻혀 있는 경우가 많습니다. 문제는 부분적으로 노출된 매복 사랑니입니다. 잇몸 덮개 아래로 세균이 들어가 붓고 아픈 지치주위염이 반복되고, 칫솔이 닿지 않아 사랑니와 바로 앞 어금니 사이에 충치가 잘 생깁니다. 특히 앞 어금니 뿌리 쪽에 생기는 충치는 발견이 늦어 멀쩡한 어금니까지 잃게 만드는 주범입니다. 드물게 매복치 주변으로 물혹(함치성 낭종)이 생겨 턱뼈를 넓게 파괴하기도 합니다. 증상이 없어도 파노라마로 방향과 상태를 확인해 문제 소지가 있으면 예방적 발치를 고려하는 것이 일반적이며, 아래턱 신경관과 가까운 경우 CT로 정밀 분석 후 안전하게 계획합니다. 뿌리가 완성되기 전인 10대 후반~20대 초반이 발치 난이도와 회복 면에서 유리한 시기입니다.', related: 'wisdom' },
  { term: '치성 감염(치아 원인 붓기)', reading: 'Odontogenic Infection', category: '증상·질환', def: '충치나 치주염에서 시작된 세균 감염이 치아 주변 조직을 넘어 턱과 얼굴 부위로 퍼진 상태입니다. 뿌리 끝 고름이 뼈를 뚫고 나오면 잇몸이 볼록하게 붓고(농양), 더 진행되면 볼·턱밑이 눈에 띄게 붓고 열이 나며, 심한 경우 입이 잘 벌어지지 않거나 침 삼키기가 힘들어집니다. 목 깊은 공간으로 퍼지면 기도를 위협할 수 있어 입원 치료가 필요한 응급 상황이 되기도 합니다. 치료의 원칙은 원인 제거입니다. 항생제는 퍼진 염증을 잡는 보조 수단일 뿐, 근본 치료는 원인 치아의 신경치료나 발치, 고름 주머니의 절개 배농입니다. 항생제만 먹고 부기가 가라앉았다고 원인 치아를 방치하면 반드시 재발하며 그때마다 더 심해집니다. 잇몸의 뾰루지(누공)에서 고름이 나오면 통증이 줄어 방치하기 쉬운데, 이는 감염이 진행 중이라는 표시입니다. 얼굴 부기·발열·개구 제한이 동반되면 미루지 말고 즉시 진료를 받아야 합니다.', related: 'endo' },
  { term: '교모·마모·침식', reading: 'Tooth Wear', category: '증상·질환', def: '충치가 아닌데도 치아가 닳아 없어지는 현상으로, 원인에 따라 세 가지로 나뉩니다. 교모는 치아끼리 맞닿아 닳는 것으로 이갈이와 노화가 주원인이며 씹는 면이 평평해집니다. 마모는 외부 물질에 의한 닳음으로, 대표적으로 잘못된 칫솔질이 치아 목 부분을 패이게 합니다. 침식은 산에 의해 치아가 녹는 것으로 탄산음료·과일주스·와인 같은 산성 음식, 역류성 식도염의 위산, 잦은 구토가 원인이며 치아 전체가 매끈하고 둥글게 녹는 양상을 보입니다. 법랑질이 닳아 속의 노란 상아질이 드러나면 치아가 노랗고 짧아 보이고 시림이 생기며, 심하면 교합 높이 자체가 낮아져 얼굴 아래쪽이 짧아지는 변화까지 옵니다. 관리 요령으로, 산성 음료 직후에는 법랑질이 일시적으로 물러져 있으므로 바로 칫솔질하지 말고 물로 헹군 뒤 30분 후에 닦는 것이 좋습니다. 이갈이는 나이트가드로 보호하고, 닳음이 심한 경우 레진·크라운으로 높이와 형태를 회복하는 치료가 필요합니다.', related: 'prosthetics' },
  { term: '혀 백태와 혀 관리', reading: 'Tongue Coating', category: '예방·관리', def: '혀 표면에 하얗게 끼는 백태는 죽은 세포, 음식 찌꺼기, 세균이 혀의 미세한 돌기 사이에 쌓인 것입니다. 혀 뒤쪽은 침의 자정 작용이 잘 미치지 않아 백태가 특히 잘 끼며, 이곳의 세균이 만드는 휘발성 황화합물이 입냄새 원인의 절반 이상을 차지합니다. 즉 구취 관리의 첫 순서는 가글이 아니라 혀 닦기입니다. 방법은 간단합니다. 혀클리너(혀 스크래퍼)를 혀 안쪽 깊숙이 대고 앞으로 부드럽게 3~5회 쓸어내리며, 칫솔보다 전용 클리너가 구역감이 덜하고 효과적입니다. 힘을 세게 주면 혀 돌기가 상하므로 부드럽게 하는 것이 요령입니다. 백태가 갑자기 두꺼워졌다면 구강 건조, 입호흡, 발열성 질환, 항생제 복용 등이 배경일 수 있고, 닦아도 지워지지 않는 흰 반점이나 통증이 있는 병변은 구강 캔디다증·백반증 등의 감별이 필요해 진료 대상입니다. 하루 한 번 아침 양치 때 혀까지 닦는 습관이 구취와 세균 관리의 가성비 높은 방법입니다.' },
  { term: '치약 선택법', reading: 'Toothpaste Guide', category: '예방·관리', def: '치약은 목적에 맞는 성분을 보고 고르는 것이 핵심입니다. 가장 중요한 기준은 불소 함량으로, 충치 예방을 위해 성인은 1,000~1,500ppm의 불소 함유 치약이 권장됩니다. 시린 증상이 있다면 질산칼륨이나 인산삼칼슘 등 지각과민 완화 성분이 든 시린이 전용 치약을 최소 2~4주 꾸준히 써야 효과가 나타납니다. 잇몸이 약하면 잇몸 질환 보조 성분이 든 제품이 도움이 될 수 있으나, 치약은 어디까지나 보조 수단이며 치석 제거(스케일링)를 대신할 수 없습니다. 미백 치약은 표면 착색을 닦아내는 연마제 위주라 치아 자체 색을 바꾸지는 못하며, 연마력이 강한 제품을 세게 오래 쓰면 치아가 패일 수 있어 마모증이 있는 분은 피하는 것이 좋습니다. 치약 양은 칫솔모의 1/3~1/2이면 충분하고, 양치 후 물로 여러 번 헹구기보다 가볍게 1~2회만 헹구는 것이 불소 효과를 유지하는 요령입니다. 결국 어떤 치약이든 올바른 칫솔질 방법이 효과의 대부분을 결정합니다.', related: 'cavity' },
  { term: '가글(구강청결제) 사용법', reading: 'Mouthwash', category: '예방·관리', def: '가글은 칫솔질을 대체하는 것이 아니라 보완하는 보조 수단입니다. 플라크는 끈끈한 막이라 액체만으로는 제거되지 않으므로, 가글의 역할은 칫솔·치실이 끝난 뒤 남은 세균을 줄이고 불소를 공급하는 마무리입니다. 종류별로 목적이 다릅니다. 불소 가글은 충치 예방에, 세틸피리디늄(CPC) 계열은 일상적인 세균 억제에 적합합니다. 클로르헥시딘 가글은 살균력이 가장 강해 잇몸 치료나 수술 후에 처방되지만, 장기간 사용하면 치아 착색과 미각 변화가 생길 수 있어 단기 처방 용도로만 써야 합니다. 알코올 함량이 높은 제품은 입안을 건조하게 만들어 구취를 오히려 악화시킬 수 있으므로, 구강건조가 있는 분은 무알코올 제품을 고르는 것이 좋습니다. 사용 시점도 중요합니다. 불소치약으로 양치한 직후 바로 가글하면 치약의 불소를 씻어낼 수 있어, 양치와 시간 간격을 두고 사용하는 것이 권장됩니다. 가글로 입냄새가 계속 가려지기만 한다면 원인(치석·치주염·백태) 치료가 먼저입니다.' },
  { term: '전동칫솔', reading: 'Electric Toothbrush', category: '예방·관리', def: '모터의 진동이나 회전으로 칫솔질을 돕는 도구로, 연구들에서 수동 칫솔 대비 플라크 제거와 치은염 감소에 다소 우수한 결과가 보고되어 있습니다. 다만 차이를 만드는 것은 도구 자체보다 사용법입니다. 아무리 좋은 전동칫솔도 잇몸 경계와 치아 사이에 모가 닿지 않으면 소용이 없고, 반대로 수동 칫솔도 정확한 회전법으로 닦으면 충분히 깨끗합니다. 전동칫솔이 특히 유용한 경우는 손 힘이나 세밀한 조작이 어려운 어르신과 어린이, 교정장치 착용자, 칫솔질 시간이 늘 부족한 분들입니다. 압력 센서가 있는 제품은 세게 닦는 습관을 교정해 잇몸 손상과 치경부 마모를 막는 데도 도움이 됩니다. 사용법의 핵심은 문지르지 않는 것입니다. 기계가 움직임을 만들어주므로, 칫솔모를 치아와 잇몸 경계에 45도로 대고 치아 하나당 몇 초씩 머물며 천천히 이동하기만 하면 됩니다. 어떤 칫솔을 쓰든 치아 사이는 닦이지 않으므로 치실·치간칫솔 병행은 여전히 필수입니다.' },
  { term: '워터픽(구강세정기)', reading: 'Water Flosser', category: '예방·관리', def: '물줄기를 분사해 치아 사이와 잇몸 경계의 음식물 찌꺼기를 씻어내는 기구입니다. 사용감이 시원하고 넓은 부위를 빠르게 헹굴 수 있어 인기가 높지만, 역할을 정확히 아는 것이 중요합니다. 워터픽은 음식물 잔사 제거와 잇몸 마사지에는 효과적이지만, 치아 면에 달라붙은 끈끈한 플라크를 긁어내는 힘은 치실·치간칫솔에 미치지 못합니다. 따라서 치실을 대체하는 도구가 아니라 보완하는 도구로 쓰는 것이 바람직합니다. 워터픽이 특히 빛나는 경우는 따로 있습니다. 교정장치 주변, 임플란트와 브릿지 아래처럼 치실이 들어가기 어려운 구조물 주위의 세척에는 매우 유용하고, 손 조작이 불편한 분들에게도 좋은 대안입니다. 사용할 때는 낮은 수압부터 시작해 적응하고, 물줄기를 잇몸 경계에 직각으로 대고 치아를 따라 천천히 이동합니다. 사용 후 물탱크를 비우고 건조해 세균 번식을 막는 관리도 필요합니다. 기본기(칫솔+치실)에 더해질 때 가치가 커지는 도구입니다.' },
  { term: '자일리톨', reading: 'Xylitol', category: '예방·관리', def: '자작나무 등에서 얻는 천연 감미료로, 설탕과 비슷한 단맛을 내지만 충치균이 이용하지 못하는 당알코올입니다. 충치균(뮤탄스균)은 자일리톨을 먹이로 착각해 흡수하지만 분해하지 못해 에너지만 소모하게 되고, 반복되면 균의 활동성과 수가 줄어드는 효과가 보고되어 있습니다. 설탕과 달리 산을 만들지 않으므로 치아를 녹이지 않고, 씹는 동안 침 분비를 촉진해 입안의 산을 씻어내고 재광화를 돕는 부수 효과도 있습니다. 효과를 보려면 조건이 있습니다. 자일리톨 함량이 충분히 높은 제품(감미료 중 자일리톨 비율이 높은 것)을, 식후에, 하루 3회 이상 꾸준히 씹는 것이 연구에서 효과를 보인 사용법입니다. 소량 함유 제품을 가끔 씹는 것으로는 큰 의미가 없습니다. 주의할 점도 있습니다. 한 번에 많이 섭취하면 복부 팽만과 설사를 일으킬 수 있고, 개에게는 매우 위험한 성분이므로 반려견이 먹지 않게 해야 합니다. 어디까지나 칫솔질의 보조 수단이지 대체재는 아닙니다.', related: 'cavity' },
  { term: '설탕과 충치의 관계', reading: 'Sugar & Caries', category: '예방·관리', def: '충치 예방에서 설탕의 총량보다 더 중요한 것은 섭취 빈도와 형태입니다. 당분이 입에 들어올 때마다 충치균이 산을 만들어 약 20~30분간 치아가 녹는 산성 환경이 되고, 이후 침이 산을 중화하며 회복됩니다. 같은 양의 단것이라도 한 번에 먹으면 산 공격이 1회로 끝나지만, 조금씩 자주 먹으면 입안이 하루 종일 산성에 머물러 충치 위험이 훨씬 커집니다. 사탕을 물고 다니는 습관, 달콤한 커피를 오전 내내 홀짝이는 습관이 위험한 이유입니다. 형태도 중요합니다. 캐러멜·젤리·말린 과일처럼 치아에 들러붙는 끈적한 당과, 탄산음료·주스처럼 산까지 함께 든 음료가 최악의 조합입니다. 반면 식사에 포함된 당은 침 분비가 활발한 상태라 상대적으로 영향이 적습니다. 현실적인 수칙은 이렇습니다. 단것은 식사 직후 디저트로 먹고, 간식 횟수를 줄이고, 단 음료 후에는 물로 헹구고, 자기 전 당 섭취는 피하는 것. 빈도를 줄이는 것이 총량을 줄이는 것보다 효과적입니다.', related: 'cavity' },
  { term: '입호흡과 구강 건강', reading: 'Mouth Breathing', category: '증상·질환', def: '코가 아닌 입으로 숨 쉬는 습관은 구강 건강 전반에 영향을 줍니다. 입으로 숨을 쉬면 입안이 지속적으로 건조해지는데, 침의 세정·중화·항균 기능이 떨어지면서 충치, 잇몸 염증, 입냄새, 앞니 착색이 늘어납니다. 잠잘 때 입을 벌리고 자는 사람이 아침에 입이 바싹 마르고 냄새가 심한 것이 대표적인 예입니다. 성장기 어린이에게는 영향이 더 큽니다. 혀가 낮게 위치하고 입이 늘 열려 있으면 위턱이 좁고 길게 자라 무턱·돌출입 경향의 얼굴형과 부정교합으로 이어질 수 있다는 점이 알려져 있어, 소아의 만성 입호흡은 조기에 원인을 찾는 것이 중요합니다. 원인은 비염·축농증·아데노이드 비대 같은 코막힘 문제가 많아 이비인후과 진료가 함께 필요할 수 있습니다. 성인은 수면 중 구강 건조가 심하면 가습, 취침 전 수분 섭취, 입벌림 방지 테이프 등이 보조가 되고, 건조로 인한 충치·잇몸 위험이 높아진 만큼 정기검진과 불소 관리를 강화하는 것이 좋습니다.' },
  { term: '구강암 자가점검', reading: 'Oral Cancer Screening', category: '증상·질환', def: '구강암은 혀, 잇몸, 볼 점막, 입천장, 입술 등 입안 어디에나 생길 수 있으며, 조기 발견 시 예후가 크게 좋아지지만 늦게 발견되는 경우가 많은 암입니다. 초기에는 통증이 없는 경우가 많아 단순 구내염으로 오인하고 방치하기 쉽기 때문입니다. 기억해야 할 경고 신호는 다음과 같습니다. 3주 이상 낫지 않는 궤양이나 상처, 닦아도 지워지지 않는 흰 반점(백반증)이나 붉은 반점(홍반증), 입안이나 목의 멍울, 원인 없이 흔들리는 치아, 지속되는 입안 감각 이상이나 출혈, 삼킴 곤란 등입니다. 일반 구내염은 아무리 커도 2주 내에 아무는 것이 정상이므로, 3주가 기준선입니다. 주요 위험 요인은 흡연과 음주(병행 시 위험이 곱으로 증가), 맞지 않는 틀니·날카로운 치아에 의한 만성 자극, HPV 감염 등입니다. 한 달에 한 번 밝은 거울 앞에서 혀 아래와 옆, 볼 안쪽을 살펴보는 자가점검 습관, 그리고 정기검진 때 점막까지 확인받는 것이 조기 발견의 지름길입니다.' },
  { term: '오스템·스트라우만 등 임플란트 브랜드', reading: 'Implant Brands', category: '재료·장비', def: '임플란트 픽스처는 제조사에 따라 표면 처리 기술, 나사 디자인, 연결 구조가 조금씩 다릅니다. 국내에서 많이 쓰이는 브랜드로는 오스템·덴티움 등 국산 대표 주자와, 스트라우만·노벨바이오케어 등 장기 임상 데이터가 축적된 글로벌 브랜드가 있습니다. 국산 브랜드는 세계 시장에서도 점유율 상위권에 오를 만큼 품질이 검증되었고 가격 접근성과 부품 수급이 좋으며, 글로벌 프리미엄 브랜드는 수십 년의 장기 추적 연구와 특수 상황(뼈가 약한 경우 등)에 대한 옵션이 강점으로 꼽힙니다. 다만 임플란트의 성공을 좌우하는 것은 브랜드보다 정확한 진단과 식립, 그리고 사후 관리라는 점이 중요합니다. 어떤 브랜드든 검증된 정품을 사용하고, 어떤 제품이 식립되었는지 기록(임플란트 수첩 등)을 받아두는 것이 좋습니다. 나중에 다른 병원에서 유지 관리를 받을 때 브랜드 정보가 있으면 호환 부품으로 신속한 대응이 가능하기 때문입니다. 상담 시 사용하는 브랜드와 그 이유를 물어보는 것은 환자의 당연한 권리입니다.', related: 'implant' },
  { term: '골유착', reading: 'Osseointegration', category: '구조·해부', def: '임플란트 표면과 뼈가 직접 단단하게 결합하는 현상으로, 현대 임플란트를 가능하게 만든 핵심 원리입니다. 1960년대 스웨덴의 브로네마르크 교수가 토끼 뼈에 심은 티타늄이 뼈와 하나처럼 붙어버린 것을 발견하면서 시작되었고, 이후 치과 임플란트의 과학적 토대가 되었습니다. 티타늄을 뼈에 심으면 뼈 세포가 임플란트 표면을 이물질로 배척하지 않고 그 위에 직접 새 뼈를 만들어 붙이며, 이 결합이 완성되면 씹는 힘을 견디는 인공 치아 뿌리가 됩니다. 골유착에는 시간이 필요합니다. 통상 아래턱은 2~3개월, 뼈가 무른 위턱은 3~6개월가량 기다리며, 뼈이식을 병행한 경우 더 길어집니다. 이 기간에 임플란트가 미세하게라도 흔들리면 뼈 대신 연조직이 끼어들어 실패하므로, 치유 기간을 지키는 것이 성공의 조건입니다. 최근 임플란트 표면 처리 기술의 발전으로 골유착 속도와 성공률이 계속 향상되어 왔습니다. 흡연과 조절되지 않는 당뇨는 골유착을 방해하는 대표 요인입니다.', related: 'implant' },
  { term: '치아 신경(치수신경)의 통증 신호', reading: 'Tooth Pain Signals', category: '증상·질환', def: '치아 통증의 양상은 문제의 위치와 단계를 알려주는 중요한 단서입니다. 찬 것에 짧게 시리고 자극이 사라지면 금방 괜찮아지는 통증은 지각과민이나 초기 충치 단계로, 신경이 아직 건강하다는 신호입니다. 반면 뜨거운 것에 아프거나, 자극이 없어도 지끈거리고, 밤에 누우면 욱신거려 잠을 깨는 통증은 신경에 비가역적 염증(치수염)이 진행된 신호로 신경치료가 필요한 단계일 가능성이 높습니다. 씹을 때만 아픈 통증은 균열이나 뿌리 끝 염증, 잇몸 문제를 시사합니다. 주의할 것은 통증이 갑자기 사라지는 경우입니다. 나은 것이 아니라 신경이 완전히 죽어 통증 신호를 보내지 못하게 된 것일 수 있으며, 감염은 조용히 뿌리 끝과 뼈로 진행됩니다. 시간이 지나 잇몸이 붓거나 얼굴까지 부으면 치료가 훨씬 커집니다. 통증은 불편한 경고이지만 치아를 살릴 기회를 주는 신호이기도 하므로, 진통제로 넘기지 말고 통증의 양상을 기억해 진료 시 정확히 전달하는 것이 좋습니다.', related: 'endo' },
  { term: '치수염', reading: 'Pulpitis', category: '증상·질환', def: '치아 속 신경과 혈관 조직(치수)에 염증이 생긴 상태로, 극심한 치통의 가장 흔한 원인입니다. 주원인은 깊은 충치를 통한 세균 침입이며, 치아 균열, 반복된 치료 자극, 심한 마모로도 생깁니다. 치수염은 회복 가능성에 따라 둘로 나뉩니다. 가역성 치수염은 자극이 있을 때만 짧게 아프고 원인(충치)을 제거하면 신경이 회복될 수 있는 단계입니다. 비가역성 치수염은 자극이 없어도 지끈거리고, 뜨거운 것에 아프고, 누우면 심해져 밤잠을 깨우는 단계로, 이때는 신경이 살아나지 못해 신경치료가 필요합니다. 치아는 단단한 벽으로 둘러싸인 밀폐 공간이라 염증으로 조직이 부어도 압력이 빠져나갈 곳이 없어, 신체에서 손꼽히게 심한 통증이 생기는 것입니다. 방치하면 신경이 괴사하며 통증이 일시적으로 사라졌다가, 감염이 뿌리 끝 뼈로 퍼져 더 큰 문제로 돌아옵니다. 뜨거운 것에 아프기 시작했다면 미루지 말라는 것이 치수염의 교훈입니다.', related: 'endo' },
  { term: '치근단 농양', reading: 'Periapical Abscess', category: '증상·질환', def: '죽은 신경 조직에서 번식한 세균이 뿌리 끝 바깥 뼈까지 퍼져 고름 주머니를 만든 상태입니다. 충치나 균열로 신경이 감염된 뒤 치료 없이 시간이 지나면 도달하는 단계로, 치아를 살짝만 두드려도 울리는 통증, 치아가 솟은 느낌, 씹을 때 아픔이 특징입니다. 고름이 뼈를 뚫고 나오면 잇몸에 뾰루지 같은 구멍(누공)이 생겨 고름이 배출되는데, 이때 압력이 빠져 통증이 줄어들기 때문에 나았다고 오해하고 방치하기 쉽습니다. 하지만 감염원은 그대로여서 뼈 파괴는 계속되고, 면역이 떨어지면 얼굴이 붓는 급성 감염으로 번질 수 있습니다. 치료의 핵심은 감염의 근원인 뿌리 속 조직을 제거하는 신경치료이며, 부기가 심하면 절개 배농과 항생제를 병행합니다. 신경치료로 해결되지 않는 경우 치근단절제술, 그마저 어려우면 발치를 고려합니다. 엑스레이에서 뿌리 끝의 검은 동그라미로 확인되므로, 증상이 없더라도 정기검진 촬영에서 우연히 발견되어 치아를 살리는 경우도 많습니다.', related: 'endo' },
  { term: '크라운 수명과 재치료', reading: 'Crown Longevity', category: '치료·시술', def: '크라운의 평균 수명은 관리 상태에 따라 크게 달라지지만 통상 7~15년 정도로 알려져 있으며, 관리가 좋으면 20년 이상 쓰는 경우도 많습니다. 크라운 자체가 닳거나 깨지는 것보다 더 흔한 교체 사유는 크라운과 치아 경계 틈으로 세균이 침투해 생기는 이차 충치입니다. 크라운 밑 충치는 겉에서 보이지 않고 신경치료된 치아는 통증도 없어, 냄새가 나거나 크라운이 흔들릴 때쯤엔 이미 속이 크게 상해 있는 경우가 많습니다. 크라운 수명을 늘리는 방법은 명확합니다. 경계부(크라운과 잇몸 사이)를 치실과 치간칫솔로 매일 청소하고, 정기검진에서 경계부 상태와 엑스레이를 점검받고, 이갈이가 있다면 나이트가드로 보호하는 것입니다. 오래된 크라운에서 잇몸이 검게 비치거나, 음식물이 계속 끼거나, 씹을 때 미세한 불편이 시작되면 교체 신호일 수 있습니다. 문제가 커지기 전에 재치료하면 치아를 살려 다시 크라운을 할 수 있지만, 늦으면 발치로 이어질 수 있습니다.', related: 'prosthetics' },
  { term: '라미네이트와 크라운의 차이', reading: 'Veneer vs Crown', category: '치료·시술', def: '둘 다 치아를 세라믹으로 감싸는 보철이지만 삭제 범위와 목적이 다릅니다. 라미네이트는 치아 앞면만 0.3~0.7mm가량 얇게 다듬고 손톱처럼 얇은 세라믹을 붙이는 방식으로, 치아 삭제량이 적어 건강한 치아 구조를 최대한 보존합니다. 색과 모양 개선이 주목적인 심미 치료에 적합하며, 주로 앞니에 적용합니다. 크라운은 치아 전체를 360도 감싸는 방식으로 삭제량은 많지만, 그만큼 치아를 사방에서 감싸 보호하고 강한 씹는 힘을 견딥니다. 충치·신경치료·파절로 치아 구조가 많이 손상된 경우, 어금니처럼 힘을 받는 부위에 적합합니다. 선택 기준은 치아의 남은 건강 상태입니다. 구조가 건강하고 심미 개선이 목적이면 삭제가 적은 라미네이트가 유리하고, 이미 손상이 크거나 신경치료를 받았다면 보호 기능이 있는 크라운이 안전합니다. 이갈이가 심한 분은 라미네이트 파절 위험이 높아 사전 평가가 필요합니다. 치아 보존의 원칙상, 가능한 한 덜 깎는 옵션부터 검토하는 것이 바람직합니다.', related: 'aesthetic' },
  { term: '레진과 세라믹의 차이', reading: 'Resin vs Ceramic', category: '재료·장비', def: '충치 치료 후 빈 공간을 메우는 대표 재료인 레진과 세라믹은 각각 장단점이 뚜렷합니다. 레진은 플라스틱 계열 복합재료로, 치과에서 당일 직접 채워 넣고 빛으로 굳히는 직접 수복 방식입니다. 한 번 내원으로 끝나고, 치아 삭제량이 적으며, 비용이 상대적으로 낮은 것이 장점입니다. 다만 강도와 마모 저항이 세라믹보다 낮고, 세월이 지나면 변색되며, 넓은 부위 수복에서는 굳을 때 수축으로 인한 미세 틈 위험이 있습니다. 세라믹(인레이·온레이·크라운)은 본을 떠서 기공 과정을 거쳐 제작하는 간접 수복 방식으로, 두 번 내원이 필요하지만 강도·변색 저항·정밀한 형태 재현이 우수해 범위가 큰 수복에 유리합니다. 선택의 기준은 충치의 크기와 위치입니다. 작고 얕은 충치는 레진으로 충분하고 오히려 치아 보존에 유리하며, 씹는 면을 넓게 차지하는 충치나 힘을 크게 받는 어금니는 세라믹이 오래갑니다. 재료보다 중요한 것은 충치를 완전히 제거하고 경계를 정밀하게 마무리하는 술식의 완성도입니다.', related: 'cavity' },
  { term: '본뜨기(인상채득)', reading: 'Dental Impression', category: '치료·시술', def: '크라운·틀니·교정장치 등을 만들기 위해 치아와 잇몸의 형태를 정밀하게 복제하는 과정입니다. 전통적 방식은 말랑한 고무 재질(인상재)을 담은 트레이를 입에 물고 몇 분간 굳혀 음형을 얻은 뒤 석고를 부어 모형을 만드는 것으로, 정확도는 검증되어 있으나 구역감이 있는 분들에게는 힘든 과정입니다. 인상의 정밀도는 보철물의 운명을 결정합니다. 본이 부정확하면 크라운 경계에 미세 틈이 생겨 이차 충치의 통로가 되고, 잘 맞지 않는 보철은 잇몸 염증과 음식물 끼임의 원인이 됩니다. 그래서 본뜨기 전에 잇몸 출혈을 조절하고 치아 경계선을 선명하게 노출시키는 준비 과정이 중요합니다. 최근에는 구강스캐너로 입안을 촬영해 디지털 데이터로 대체하는 디지털 인상이 확산되어, 구역감 없이 더 빠르고 정밀한 채득이 가능해졌습니다. 구역감이 심한 분은 미리 말씀하시면 표면마취 스프레이, 트레이 크기 조정, 디지털 스캔 등으로 편하게 진행할 방법이 있습니다.', related: 'prosthetics' },
  { term: '치과 진정 웃음가스(아산화질소)', reading: 'Nitrous Oxide', category: '치료·시술', def: '코에 씌운 마스크로 아산화질소와 산소 혼합 기체를 마시며 긴장을 완화하는 가장 가벼운 단계의 진정법입니다. 웃음가스라는 별명처럼 마시면 기분이 편안해지고 몸이 살짝 붕 뜨는 느낌이 들며, 치료에 대한 불안과 통증 민감도가 줄어듭니다. 의식은 완전히 유지되어 대화가 가능하고, 가장 큰 장점은 회복 속도입니다. 흡입을 멈추고 산소로 전환하면 몇 분 내에 약효가 사라져, 성인은 치료 후 곧바로 일상 복귀와 운전까지 가능한 수준으로 회복됩니다. 주사가 필요 없어 소아 치과에서 특히 널리 쓰이며, 겁이 많은 어린이가 치과에 좋은 기억을 갖게 하는 데 도움이 됩니다. 성인도 가벼운 치과공포, 구역 반사가 있는 경우 좋은 선택지입니다. 다만 진정 깊이가 얕아 공포가 매우 심한 경우에는 정맥 진정(수면치료)이 더 적합할 수 있고, 코가 심하게 막힌 상태나 일부 호흡기 질환에서는 적용이 제한됩니다. 안전성이 높고 부작용이 적어 문턱이 낮은 진정 방법입니다.' },
  { term: '치아 홈 패임(설측면·교합면 구조)', reading: 'Pits & Fissures', category: '구조·해부', def: '어금니 씹는 면의 골짜기처럼 파인 홈(열구)과 오목한 점(소와)을 말합니다. 이 구조는 음식을 효율적으로 부수기 위한 자연의 설계이지만, 동시에 충치가 가장 잘 생기는 지점이기도 합니다. 홈의 폭은 칫솔모 하나보다 좁고 바닥은 법랑질이 얇아, 세균과 음식 찌꺼기가 들어가면 칫솔로는 제거할 수 없고 산 공격에도 취약합니다. 실제 어린이·청소년 충치의 대부분이 이 홈에서 시작됩니다. 홈 충치의 특징은 겉보기와 속이 다르다는 점입니다. 입구는 좁은 점처럼 보여도 속에서 넓게 퍼지는 형태로 진행되어, 겉으로 멀쩡해 보이는 치아 속에 큰 충치가 숨어 있기도 합니다. 검은 선처럼 보이는 착색이 모두 충치는 아니지만, 감별에는 시진과 엑스레이, 필요시 레이저 충치 진단기가 활용됩니다. 예방법은 명확합니다. 영구치 어금니가 나오는 시기에 홈메우기(실런트)로 홈 자체를 밀봉하고, 불소로 법랑질을 강화하며, 정기검진으로 초기 변화를 추적하는 것입니다.', related: 'cavity' },
  { term: '치아교정과 브라켓', reading: 'Orthodontic Bracket', category: '치료·시술', def: '치아 표면에 부착하는 작은 장치(브라켓)와 이를 연결하는 철사(와이어)의 힘으로 치아를 서서히 원하는 위치로 이동시키는 치료입니다. 치아는 잇몸뼈 속에 단단히 박혀 있는 것 같지만, 지속적으로 약한 힘을 가하면 뼈가 한쪽에서는 흡수되고 반대쪽에서는 새로 만들어지면서 치아가 이동합니다. 이 생물학적 원리 덕분에 나이와 무관하게 교정이 가능하며, 성인 교정도 활발히 이루어집니다. 브라켓은 금속형과 치아색 세라믹형이 있고, 치아 안쪽에 붙이는 설측 교정도 있습니다. 교정 기간은 보통 1년 반에서 3년 정도로 개인차가 크며, 4~6주 간격의 정기 조정이 필요합니다. 교정 중에는 브라켓 주변에 음식물이 잘 끼어 충치·잇몸염증 위험이 높아지므로 교정용 칫솔과 치간칫솔을 활용한 꼼꼼한 관리가 필수입니다. 교정은 심미 개선뿐 아니라 씹는 기능, 발음, 청결 관리 용이성까지 개선하는 치료로, 삐뚤어진 치아는 칫솔이 닿지 않는 사각지대를 만들어 충치와 잇몸병의 원인이 되기 때문입니다.' },
  { term: '투명교정(투명장치 교정)', reading: 'Clear Aligner', category: '치료·시술', def: '치아에 브라켓을 붙이는 대신, 투명한 플라스틱 틀(얼라이너)을 끼워 치아를 이동시키는 교정 방법입니다. 디지털 스캔으로 현재 치아 상태를 분석한 뒤, 최종 목표까지의 이동 과정을 여러 단계로 나누어 단계별 장치를 제작합니다. 환자는 1~2주마다 다음 단계 장치로 교체하며, 각 장치가 치아를 조금씩 밀어 누적 이동을 만들어냅니다. 가장 큰 장점은 눈에 거의 띄지 않는 심미성과, 식사·양치 시 빼놓을 수 있어 구강 위생 관리가 쉽다는 점입니다. 브라켓 교정처럼 장치가 볼이나 입술을 긁는 불편도 적습니다. 다만 성공의 열쇠는 착용 시간입니다. 하루 20~22시간 착용해야 계획대로 치아가 움직이며, 착용 시간이 부족하면 치료가 지연되거나 계획과 어긋납니다. 스스로 빼고 낄 수 있다는 장점이 곧 단점이 될 수 있는 것입니다. 또한 심한 회전이나 큰 이동이 필요한 복잡한 케이스에서는 브라켓 교정이 더 효율적일 수 있어, 정밀 진단을 통해 적합한 방법을 선택하는 것이 중요합니다.' },
  { term: '유지장치(리테이너)', reading: 'Retainer', category: '재료·장비', def: '교정 치료가 끝난 뒤 치아가 원래 자리로 되돌아가는 것을 막기 위해 착용하는 장치입니다. 교정으로 이동한 치아 주변의 뼈와 잇몸 섬유는 아직 새 위치에 완전히 적응하지 못한 상태여서, 장치를 제거하면 치아를 원래 자리로 끌어당기는 힘이 작용합니다. 이를 회귀 현상이라 하며, 유지장치 없이 방치하면 수년간의 교정 결과가 서서히 무너질 수 있습니다. 유지장치는 크게 두 종류입니다. 가철식은 투명한 틀이나 철사 달린 장치를 빼고 낄 수 있는 형태로, 초기에는 종일 착용하다가 점차 밤에만 착용하는 식으로 줄여갑니다. 고정식은 앞니 안쪽에 가는 철사를 접착해 두는 방식으로, 착용을 잊을 염려가 없지만 치실 사용에 요령이 필요합니다. 유지 기간에 대해 흔히 오해가 있는데, 최소 1~2년이 아니라 사실상 평생 관리 개념으로 접근하는 것이 안전합니다. 나이가 들며 치아는 자연적으로도 조금씩 움직이기 때문입니다. 유지장치가 파손되거나 분실되면 방치하지 말고 빠르게 재제작해야 회귀를 막을 수 있습니다.' },
  { term: '골재생 유도술(GBR)', reading: 'Guided Bone Regeneration', category: '치료·시술', def: '임플란트를 심기에 잇몸뼈가 부족할 때, 뼈이식재와 차폐막을 이용해 뼈가 다시 자라도록 유도하는 수술입니다. 치아를 빼고 오래 방치하거나 잇몸병이 진행되면 잇몸뼈가 흡수되어 얇아지고 낮아지는데, 이 상태로 임플란트를 심으면 고정이 불안정하고 장기 성공률이 떨어집니다. 골재생 유도술의 원리는 공간 확보와 경쟁 차단입니다. 뼈가 부족한 부위에 뼈이식재를 채워 공간을 만들고, 그 위를 차폐막으로 덮어 잇몸 세포가 먼저 들어오는 것을 막습니다. 잇몸 세포는 뼈 세포보다 자라는 속도가 빨라, 막이 없으면 뼈가 생겨야 할 공간을 잇몸이 차지해버리기 때문입니다. 차폐막 아래에서 뼈 세포가 이식재를 발판 삼아 서서히 새 뼈를 만들며, 보통 4~6개월의 치유 기간이 필요합니다. 임플란트 식립과 동시에 진행하기도 하고, 뼈 부족이 심하면 골재생을 먼저 한 뒤 임플란트를 심기도 합니다. 수술 후에는 이식 부위를 혀나 칫솔로 자극하지 않고, 부기와 멍이 있을 수 있어 처방약 복용과 냉찜질 등 주의사항을 지키는 것이 성공률을 높입니다.', related: 'implant' },
  { term: '발치 즉시 임플란트', reading: 'Immediate Implant', category: '치료·시술', def: '치아를 뽑은 그 자리에, 같은 날 곧바로 임플란트를 심는 방법입니다. 전통적으로는 발치 후 잇몸뼈가 아물기를 3~6개월 기다린 뒤 임플란트를 심었지만, 조건이 맞으면 발치와 식립을 한 번에 진행해 전체 치료 기간을 크게 단축할 수 있습니다. 장점은 분명합니다. 수술 횟수가 줄고, 치료 기간이 몇 달 단축되며, 발치 후 일어나는 잇몸뼈 흡수를 줄여 잇몸 모양을 자연스럽게 보존하는 데도 유리합니다. 특히 앞니처럼 심미성이 중요한 부위에서 잇몸 라인 보존 효과가 큽니다. 다만 아무 경우에나 가능한 것은 아닙니다. 발치한 자리에 급성 염증이나 고름이 있으면 감염 위험 때문에 부적합하고, 남은 뼈의 양과 질이 임플란트를 단단히 잡아줄 수 있어야 합니다. 3D CT로 뼈 상태를 정밀 분석해 초기 고정력을 확보할 수 있다고 판단될 때 시행합니다. 상황에 따라 식립 당일 임시치아까지 연결하는 즉시 부하를 병행하기도 하지만, 이는 더 엄격한 조건이 필요합니다. 결국 핵심은 속도가 아니라 정확한 적응증 판단입니다.', related: 'implant' },
  { term: '노인 구강관리', reading: 'Geriatric Oral Care', category: '예방·관리', def: '나이가 들면 구강 환경도 함께 변합니다. 침 분비가 줄어 입이 마르고, 잇몸이 내려가 치아 뿌리가 드러나며, 오래된 보철물 주변으로 충치가 생기기 쉬워집니다. 손 근력과 시력이 떨어지면 칫솔질의 정밀도도 낮아집니다. 그래서 노년기 구강관리는 젊을 때와 다른 전략이 필요합니다. 첫째, 뿌리 충치 예방입니다. 드러난 치아 뿌리는 법랑질이 없어 충치에 매우 취약하므로, 고농도 불소치약과 정기적 불소도포가 큰 도움이 됩니다. 둘째, 구강건조 관리입니다. 복용 약물이 많을수록 입마름이 심해지는데, 물을 자주 마시고 필요시 인공타액을 활용하며, 입마름이 심하면 주치의와 약물 조정을 상의할 수 있습니다. 셋째, 보철물 점검입니다. 틀니는 매일 세척하고 밤에는 빼두며, 헐거워진 틀니와 오래된 크라운 경계는 정기적으로 점검받아야 합니다. 구강 건강은 노년기 전신 건강과 직결됩니다. 씹는 기능이 떨어지면 영양 섭취가 부실해지고, 저작 자극 감소는 인지 기능에도 영향을 준다는 연구들이 있습니다. 잘 씹는 것이 곧 건강 수명입니다.' },
  { term: '구강작열감 증후군', reading: 'Burning Mouth Syndrome', category: '증상·질환', def: '혀나 입천장, 입술 안쪽이 데인 것처럼 화끈거리고 따가운데, 검사를 해봐도 눈에 보이는 이상이 없는 상태를 말합니다. 주로 중년 이후 여성에게 많고, 아침에는 덜하다가 오후로 갈수록 심해지는 양상이 흔합니다. 화끈거림과 함께 입마름, 미각 변화(쓴맛·금속맛)를 동반하기도 합니다. 원인은 한 가지로 특정하기 어렵습니다. 구강 감각신경의 기능 이상이 핵심 기전으로 추정되며, 폐경 전후 호르몬 변화, 철분·아연·비타민B군 결핍, 구강건조, 캔디다 감염, 잘 맞지 않는 틀니, 스트레스와 불안 등이 복합적으로 관여합니다. 따라서 진단은 배제 과정입니다. 눈에 보이는 염증·감염·빈혈 등 교정 가능한 원인을 혈액검사와 구강검사로 하나씩 확인하고 치료해본 뒤, 그래도 남는 증상을 구강작열감 증후군으로 진단합니다. 치료는 원인 교정과 함께 신경 감각을 안정시키는 약물, 침 분비 촉진, 스트레스 관리 등을 병행합니다. 좋아졌다 나빠졌다를 반복하는 만성 경과가 흔하므로, 조급해하지 않고 꾸준히 관리하는 것이 중요합니다.' },
  { term: '편도결석과 입냄새', reading: 'Tonsil Stone', category: '증상·질환', def: '목젖 양옆 편도의 움푹 파인 구멍(편도와)에 음식물 찌꺼기·세균·죽은 세포가 뭉쳐 굳은 쌀알 크기의 노란 알갱이입니다. 기침이나 양치 중에 톡 튀어나오기도 하는데, 으깨보면 지독한 냄새가 나는 것이 특징입니다. 양치를 열심히 해도 입냄새가 사라지지 않는다면 편도결석이 원인일 수 있습니다. 치아와 잇몸은 건강한데 목 쪽에서 냄새가 올라오는 경우, 목에 뭔가 걸린 듯한 이물감이 함께 있는 경우 의심해볼 수 있습니다. 만성 편도염을 앓았던 분, 비염·후비루로 콧물이 목뒤로 넘어가는 분에게 잘 생깁니다. 관리의 기본은 구강과 목을 청결하게 유지하는 것입니다. 식후 물 가글과 항균 가글로 편도 주변 찌꺼기를 줄이고, 물을 자주 마셔 입안이 마르지 않게 합니다. 면봉 등으로 무리하게 파내는 것은 편도에 상처를 내 염증을 악화시킬 수 있어 권하지 않습니다. 자주 재발하며 이물감·냄새가 심하면 이비인후과에서 편도와 세척이나 수술적 치료를 상의할 수 있습니다. 입냄새의 원인은 구강 내 요인이 대부분이므로, 치과 검진으로 잇몸병·충치·혀 백태를 먼저 확인하는 것이 순서입니다.' },
  { term: '원데이 세라믹 치료(CAD/CAM)', reading: 'One-day Ceramic', category: '치료·시술', def: '구강스캐너로 치아를 촬영하고, 컴퓨터 설계(CAD)와 원내 밀링 장비(CAM)로 세라믹 보철물을 당일 제작해 부착까지 끝내는 치료 방식입니다. 전통적으로 인레이나 크라운은 본을 떠서 기공소에 보내고 완성까지 1~2주를 기다리며 임시치아로 지내야 했지만, 원데이 시스템은 이 과정을 하루로 압축합니다. 장점은 시간 단축만이 아닙니다. 임시치아 기간이 없어 그 사이 임시 접착제가 떨어지거나 치아가 시린 불편이 사라지고, 치아를 다듬은 당일 바로 밀봉하므로 세균 오염 위험도 줄어듭니다. 디지털 스캔은 구역감 없이 정밀한 데이터를 얻을 수 있고, 설계 과정에서 맞물림까지 컴퓨터로 확인합니다. 다만 모든 치료가 당일 가능한 것은 아닙니다. 심미성이 극도로 중요한 앞니 케이스나 여러 치아를 잇는 긴 브릿지는 기공사의 정밀 작업이 필요할 수 있고, 신경치료 여부 판단이 필요한 깊은 충치는 경과 관찰이 우선입니다. 장비가 아니라 진단과 적응증 판단이 치료 품질을 결정한다는 점은 변하지 않습니다.', related: 'prosthetics' },
  { term: '틀니 관리법', reading: 'Denture Care', category: '예방·관리', def: '틀니의 수명과 구강 건강은 매일의 관리 습관이 좌우합니다. 첫째, 세척은 치약이 아닌 틀니 전용 세정제나 주방세제로 합니다. 치약의 연마제는 틀니 표면에 미세한 흠집을 내고, 그 틈에 세균이 번식해 냄새와 착색의 원인이 됩니다. 흐르는 미지근한 물에서 전용 솔로 닦되, 뜨거운 물은 틀니를 변형시키므로 금물입니다. 둘째, 밤에는 반드시 빼서 물이나 세정액에 담가 보관합니다. 잇몸도 하루 종일 틀니에 눌린 압박에서 회복할 시간이 필요하며, 끼고 자면 잇몸 염증과 곰팡이 감염(의치성 구내염) 위험이 높아집니다. 건조하게 방치하면 틀니가 변형되므로 항상 물에 담가둡니다. 셋째, 틀니를 뺀 뒤 잇몸과 입천장, 혀도 부드러운 칫솔로 닦아줍니다. 넷째, 떨어뜨림 사고 예방을 위해 세면대에 물을 받아놓고 세척하는 습관이 좋습니다. 잘 맞던 틀니도 잇몸뼈가 세월에 따라 흡수되면서 헐거워지므로, 6개월~1년마다 치과에서 적합도를 점검하고 필요시 내면 조정(이장)을 받는 것이 잇몸 건강과 씹는 기능을 오래 지키는 길입니다.', related: 'prosthetics' },
  { term: '치아 사이 음식물 끼임', reading: 'Food Impaction', category: '증상·질환', def: '식사 때마다 특정 부위에 음식물이 끼는 증상은 단순한 불편이 아니라 치아가 보내는 경고 신호일 수 있습니다. 원인은 다양합니다. 치아 사이 충치로 접촉면이 무너진 경우, 오래된 보철물의 접촉이 헐거워진 경우, 잇몸병으로 치아 사이 잇몸(치간유두)이 내려앉아 공간이 생긴 경우, 치아가 기울거나 벌어진 경우 등입니다. 문제는 악순환입니다. 낀 음식물이 잇몸을 누르고 세균의 먹이가 되어 그 부위 잇몸병과 충치를 악화시키고, 잇몸이 더 내려가면 공간이 더 커져 더 잘 끼게 됩니다. 이쑤시개로 후비는 습관은 잇몸에 상처를 내고 공간을 넓혀 상황을 악화시키므로 치실이나 치간칫솔로 대체해야 합니다. 갑자기 특정 부위에 음식물이 끼기 시작했다면 그 사이 어딘가에 변화가 생겼다는 뜻이므로 방치하지 말고 검진을 받는 것이 좋습니다. 치료는 원인에 따라 충치 치료, 보철물 재제작으로 접촉면 회복, 잇몸 치료 등으로 나뉘며, 원인을 해결하면 끼임 자체가 크게 줄어듭니다.', related: 'cavity' },
  { term: '치아 시림(지각과민)', reading: 'Dentin Hypersensitivity', category: '증상·질환', def: '찬물이나 찬 공기, 단 음식에 순간적으로 찌릿한 시림을 느끼는 증상으로, 성인의 상당수가 겪는 흔한 문제입니다. 원리는 상아질 노출입니다. 치아 속층인 상아질에는 신경까지 이어지는 미세한 관(상아세관)이 무수히 뚫려 있는데, 이를 덮고 있던 법랑질이나 잇몸이 소실되면 외부 자극이 이 관을 통해 신경에 그대로 전달됩니다. 노출의 원인은 세게 옆으로 문지르는 칫솔질로 인한 치경부 마모, 잇몸 퇴축으로 인한 뿌리 노출, 이갈이·탄산음료로 인한 법랑질 소실, 균열이나 충치 등 다양합니다. 대처는 원인에 따라 다릅니다. 가벼운 지각과민은 시린이 전용치약(신경 전달을 둔화시키는 성분)을 4주 이상 꾸준히 쓰고 칫솔질 습관을 교정하면 호전되는 경우가 많습니다. 패인 부위가 뚜렷하면 레진으로 메우고, 광범위한 노출에는 불소도포나 지각과민 처치제를 시행합니다. 다만 뜨거운 것에 아프거나, 씹을 때 아프거나, 자극이 사라진 뒤에도 통증이 남는다면 단순 시림이 아니라 치수염이나 균열의 신호일 수 있으므로 정밀 검진이 필요합니다.', related: 'endo' },
  { term: '잇몸에서 피가 날 때', reading: 'Gum Bleeding', category: '증상·질환', def: '양치나 치실 사용 중 잇몸에서 피가 나는 것은 가장 흔하면서도 가장 자주 무시되는 잇몸병 신호입니다. 건강한 잇몸은 정상적인 칫솔질로 피가 나지 않습니다. 출혈은 플라크 속 세균에 대항해 잇몸에 염증 반응이 일어나 혈관이 확장되고 조직이 약해졌다는 뜻으로, 대부분 치은염 단계입니다. 이때 흔한 실수가 피가 나니까 그 부위를 살살 닦거나 피하는 것입니다. 원인인 플라크가 더 쌓여 염증이 악화되는 역설이 벌어집니다. 올바른 대응은 반대로, 피가 나더라도 부드러운 칫솔로 잇몸 경계를 더 꼼꼼히 닦고 치실을 병행하는 것입니다. 치은염 단계라면 1~2주 내에 출혈이 눈에 띄게 줄어듭니다. 그래도 계속 피가 난다면 칫솔이 닿지 않는 잇몸 속 치석이 원인일 가능성이 높아 스케일링과 잇몸 치료가 필요합니다. 한편 잇몸 전반에서 이유 없이 자주 피가 나거나 멍이 잘 드는 증상이 동반되면 혈액 질환이나 복용 약물(항응고제 등)의 영향일 수 있어 전신 상태 확인도 필요합니다. 임신 중 호르몬 변화로 출혈이 심해지는 임신성 치은염도 흔하므로 임산부는 더 세심한 관리가 좋습니다.', related: 'gum' },
  { term: '사랑니 발치 후 관리', reading: 'Post-extraction Care', category: '예방·관리', def: '사랑니 발치 후 회복의 핵심은 발치 자리에 생기는 피떡(혈병)을 지키는 것입니다. 피떡은 뼈가 아무는 기초 공사이자 천연 밴드로, 이것이 떨어져 나가면 뼈가 노출되어 극심한 통증을 겪는 드라이소켓이 생깁니다. 첫 2시간은 거즈를 꽉 물어 지혈하고, 침과 피가 고여도 뱉지 말고 삼키는 것이 좋습니다. 첫 24시간 동안은 빨대 사용, 침 뱉기, 흡연, 강한 가글을 피해야 합니다. 모두 입안에 음압을 만들거나 피떡을 씻어내는 행동입니다. 부기는 첫 48시간이 고비이므로 냉찜질을 15분 간격으로 반복하고, 3일째부터는 온찜질로 전환해 부기 해소를 돕습니다. 식사는 마취가 풀린 뒤 반대쪽으로 미지근하고 부드러운 음식부터 시작하고, 뜨겁고 맵고 딱딱한 음식은 며칠 피합니다. 양치는 당일부터 하되 발치 부위만 피해서 하고, 다음날부터 처방받은 가글이나 소금물로 부드럽게 헹굽니다. 처방 항생제는 증상이 없어도 끝까지 복용해야 합니다. 3~4일이 지나도 통증이 오히려 심해지거나, 고름·발열·입이 안 벌어지는 증상이 생기면 감염 신호이므로 바로 내원해야 합니다.', related: 'wisdom' },
  { term: '치과 엑스레이와 방사선 안전', reading: 'Dental X-ray Safety', category: '재료·장비', def: '치과 방사선 촬영에 대한 걱정은 흔하지만, 실제 노출량을 알면 안심할 수 있는 수준입니다. 우리는 일상에서도 자연 방사선에 노출되며 살아갑니다(연간 약 3mSv). 디지털 파노라마 1회는 약 0.01~0.02mSv로 이는 며칠치 자연 노출량, 비행기 국제선 왕복(약 0.1mSv)보다도 훨씬 적은 양입니다. 소형 치근단 촬영은 그보다 더 적고, 3D CT도 의과용 CT의 수십 분의 일 수준입니다. 게다가 디지털 센서의 보급으로 과거 필름 시대보다 노출량이 크게 줄었습니다. 그럼에도 치과는 정당화와 최적화 원칙을 지킵니다. 진단에 필요한 경우에만, 필요한 최소 범위로 촬영하고, 필요시 방어복을 사용합니다. 임신 중에도 응급 상황이라면 복부를 차폐하고 촬영하는 것이 진단을 포기하는 것보다 안전하다는 것이 학계의 일치된 견해이지만, 응급이 아니면 출산 후로 미루는 것이 일반적입니다. 엑스레이 없이 치과 진단은 절반만 보는 것과 같습니다. 치아 사이 충치, 뼈 속 염증, 매복치는 눈으로 볼 수 없어, 적절한 촬영은 위험이 아니라 안전을 위한 필수 과정입니다.' },
  { term: '6세 구치(첫 영구치 어금니)', reading: 'First Molar', category: '구조·해부', def: '만 6세 무렵 유치 어금니 뒤쪽에서 새로 올라오는 첫 번째 영구치 큰어금니입니다. 평생 치아 건강의 주춧돌이라 불릴 만큼 중요한 치아이지만, 역설적으로 가장 많이 썩는 치아이기도 합니다. 이유는 등장 방식에 있습니다. 유치가 빠진 자리에 나는 것이 아니라 그 뒤 잇몸을 뚫고 조용히 올라오기 때문에, 많은 부모님이 유치인 줄 알고 관리에 소홀해집니다. 게다가 완전히 올라오기까지 1년 이상 잇몸에 반쯤 덮여 있어 닦기 어렵고, 갓 나온 법랑질은 아직 단단하게 여물지 않아 충치에 특히 취약합니다. 6세 구치는 위아래 맞물림의 기준점이 되어 나머지 영구치들이 배열되는 위치를 결정하고, 씹는 힘의 상당 부분을 담당합니다. 이 치아를 어려서 잃으면 교합 전체가 무너지는 연쇄 효과가 생깁니다. 보호 전략은 명확합니다. 만 6세 전후 검진으로 맹출 상태를 확인하고, 씹는 면이 완전히 드러나면 홈메우기(실런트, 건강보험 적용)로 밀봉하며, 불소도포를 병행하고, 부모님이 마무리 양치로 뒤쪽까지 닦아주는 것입니다. 아이의 첫 영구치 어금니를 지키는 것이 평생 치아 건강의 첫 단추입니다.', related: 'cavity' },
]

// ===== 자동 공개 설정 =====
// Pages에는 크론이 없으므로 "요청 시점 일자 계산" 방식으로 공개 개수를 결정한다.
// 상태 저장이 필요 없고(D1 불필요), 배열 순서 = 공개 순서 계약을 따른다.
export const ENCY_INITIAL = 40          // 오픈 즉시 공개되는 용어 수
export const ENCY_PER_DAY = 5           // 매일(KST 자정) 추가 공개되는 용어 수
export const ENCY_LAUNCH = '2026-08-03' // KST 기준 오픈일 (이 날은 ENCY_INITIAL개만 공개)

/** KST(UTC+9) 자정 기준, 오픈일로부터 경과한 일수만큼 공개 개수를 계산 */
export function encyReleasedCount(now: Date = new Date()): number {
  const KST_OFFSET = 9 * 60 * 60 * 1000
  // 현재 시각의 KST 날짜 (자정 기준)
  const kstNow = new Date(now.getTime() + KST_OFFSET)
  const todayKst = Date.UTC(kstNow.getUTCFullYear(), kstNow.getUTCMonth(), kstNow.getUTCDate())
  // 오픈일의 KST 자정
  const [y, m, d] = ENCY_LAUNCH.split('-').map(Number)
  const launchKst = Date.UTC(y, m - 1, d)
  const daysPassed = Math.max(0, Math.floor((todayKst - launchKst) / 86400000))
  return Math.min(ENCYCLOPEDIA.length, ENCY_INITIAL + daysPassed * ENCY_PER_DAY)
}

/** 현재 시점 기준 공개된 용어 목록 (배열 앞에서부터 순서대로 공개) */
export function getReleasedEncyclopedia(now: Date = new Date()): EncyItem[] {
  return ENCYCLOPEDIA.slice(0, encyReleasedCount(now))
}

/** 내일(KST 자정) 추가 공개될 용어 수 — 티저 표시용. 풀 소진 시 0 */
export function encyTomorrowCount(now: Date = new Date()): number {
  const released = encyReleasedCount(now)
  return Math.min(ENCY_PER_DAY, ENCYCLOPEDIA.length - released)
}
